-- Generated by scripts/import_enfermeria_docente_banks.py
-- Sources: Manual de Inmunizaciones MSP 2026 and MAIS-FCI MSP 2018 docente banks.
-- Questions: 200

create extension if not exists pgcrypto;

create table if not exists public.questions (
  id uuid primary key default gen_random_uuid(),
  question_text text not null,
  option_a text not null,
  option_b text not null,
  option_c text not null,
  option_d text not null,
  correct_option text not null check (correct_option in ('A', 'B', 'C', 'D')),
  explanation text,
  category text,
  difficulty text,
  created_at timestamp with time zone default now()
);

alter table public.questions enable row level security;

drop policy if exists "Authenticated users can read questions" on public.questions;
create policy "Authenticated users can read questions"
on public.questions for select to authenticated
using (true);

insert into public.questions (
  id,
  question_text,
  option_a,
  option_b,
  option_c,
  option_d,
  correct_option,
  explanation,
  category,
  difficulty
) values
  ('701cd0a9-7314-508e-9b2e-47eb2d0930a7', 'Según el manual, ¿cómo se denomina también a la inmunidad innata y cuál es su principal característica?', 'Inmunidad natural o inespecífica; es una respuesta inmediata que no requiere exposición previa al agente agresor', 'Inmunidad adaptativa; requiere exposición previa al agente', 'Inmunidad de rebaño; depende de la cobertura vacunal poblacional', 'Inmunidad pasiva; se transfiere de un individuo a otro', 'A', 'El manual define a la inmunidad innata, también denominada natural o inespecífica, como la primera línea de defensa frente a microorganismos patógenos, una respuesta inmediata que no requiere exposición previa al agente agresor y cuya intensidad no varía ante encuentros repetidos con el mismo estímulo. Referencia: Capítulo 1. Principios de la Inmunización. 1.1.1 Inmunidad innata. Página 23.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('d636a0be-e0d5-54db-afb5-9be6b02b9760', 'Caso clínico: Una mujer embarazada de 30 semanas de gestación pregunta cómo se protegerá su bebé antes de nacer. Según el manual, ¿qué tipo de inmunidad adquiere el feto por el paso transplacentario de anticuerpos maternos IgG?', 'Inmunidad activa natural', 'Inmunidad pasiva natural', 'Inmunidad activa artificial', 'Inmunidad pasiva artificial', 'B', 'El manual clasifica la inmunidad transplacentaria (transferencia de anticuerpos maternos IgG al feto a partir de la 12ª semana de gestación) como inmunidad pasiva de tipo natural, dentro de la Tabla 1 de inmunidad adquirida o adaptativa. Referencia: Capítulo 1. Principios de la Inmunización. Tabla 1. Inmunidad adquirida o adaptativa. Página 25.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('f685486f-e25b-5359-9abe-55fb77226eac', 'Según el manual, ¿qué cobertura de vacunación se requiere aproximadamente para evitar brotes epidémicos de sarampión, dada su alta contagiosidad?', 'Superior al 80%', 'Superior al 90%', 'Superior al 95%', 'No se requiere ningún umbral específico', 'C', 'El manual indica que, debido a su alta contagiosidad, el sarampión requiere una cobertura superior al 95% para evitar brotes epidémicos, mientras que para la poliomielitis se estima necesaria una inmunización de más del 90% de la población. Referencia: Capítulo 1. Principios de la Inmunización. 1.1.3 Inmunidad de rebaño. Página 26.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('7cde921c-6152-5196-a048-6255a588f2b9', 'Según el manual, ¿cuál es la función de los adyuvantes en las vacunas y cuál es un ejemplo citado?', 'Prevenir la contaminación microbiana; ejemplo el tiomersal', 'Dar forma, consistencia y estabilidad al medicamento; ejemplo el agua', 'Eliminar la capacidad tóxica o reproductiva de los agentes patógenos; ejemplo el formaldehído', 'Potenciar de manera no específica la respuesta inmunológica frente a un antígeno determinado; ejemplo las sales de aluminio', 'D', 'El manual describe a los adyuvantes como compuestos incorporados a las vacunas con el propósito de potenciar, de manera no específica, la respuesta inmunológica frente a un antígeno determinado, citando como ejemplo las sales de aluminio (fosfato y sulfato de aluminio y potasio). Referencia: Capítulo 1. Principios de la Inmunización. 1.2.1 Componentes de las vacunas. Página 27.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('ef8f2343-1bc9-5023-91cc-cd454173d9e8', 'Según el manual, ¿qué antibiótico se menciona específicamente como componente utilizado en la fabricación de algunas vacunas, como la triple vírica, para evitar contaminación bacteriana?', 'Neomicina', 'Penicilina', 'Ceftriaxona', 'Ciprofloxacina', 'A', 'El manual indica que se añaden pequeñas cantidades de antibióticos durante la fabricación de las vacunas para evitar la contaminación bacteriana, citando como ejemplo la neomicina utilizada en vacunas como la triple vírica; además aclara que las vacunas no contienen penicilinas, cefalosporinas ni fluoroquinolonas. Referencia: Capítulo 1. Principios de la Inmunización. 1.2.1 Componentes de las vacunas. Página 27.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('2fdf04cd-7287-51ce-93c3-7f4d84f6a7cb', 'Según el manual, ¿qué son los haptenos en el contexto de la vacunación?', 'Anticuerpos de alta afinidad producidos por linfocitos B', 'Antígenos de bajo peso molecular que requieren conjugación con proteínas transportadoras para inducir una respuesta inmune efectiva', 'Componentes que eliminan la capacidad tóxica de los patógenos', 'Sustancias estabilizadoras derivadas de la gelatina', 'B', 'El manual explica que en el contexto de la vacunación, los antígenos de bajo peso molecular conocidos como haptenos requieren su conjugación con proteínas transportadoras para inducir una respuesta inmune efectiva, como ocurre en las vacunas conjugadas. Referencia: Capítulo 1. Principios de la Inmunización. Página 24.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('838512ef-470e-5f81-83a6-34522ed48d86', 'Según el índice de contenidos del manual, ¿qué capítulo aborda el registro y autorización de nuevas vacunas, así como las fases de su desarrollo?', 'Capítulo 1. Principios de la Inmunización', 'Capítulo 3. Cadena de frío', 'Capítulo 2. Producción y control de calidad de las vacunas', 'Capítulo 11. Oportunidades perdidas de vacunación', 'C', 'El manual estructura en el Capítulo 2, ''Producción y control de calidad de las vacunas'', los apartados de garantía de calidad, objetivo del control de calidad, registro y autorización de nuevas vacunas (incluyendo sus fases de desarrollo) y la vacuna ideal. Referencia: Contenido. Capítulo 2. Producción y control de calidad de las vacunas. Página 8.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('9d88827f-d25e-5385-907a-594ef6ffa02c', 'Según el glosario del manual, ¿cómo se define la ''cobertura de vacunación - administrativa''?', 'El número total de casos de una enfermedad en una población definida', 'El porcentaje de personas que rechazan la vacunación', 'El número de dosis desperdiciadas durante un período', 'El número de dosis administradas de un biológico específico dividido para la población objetivo, multiplicado por 100, en tiempo y localidad definidos', 'D', 'El glosario del manual define la cobertura de vacunación administrativa como el porcentaje que se calcula como el número de dosis administradas de un biológico específico (numerador) dividido para la población objetivo (denominador), multiplicado por 100, en tiempo y localidad geográfica definidos. Referencia: 6. Glosario de términos. Página 20-21.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('d7985d86-12cb-5e30-b7d5-9ec5ec31d2e6', 'Según el manual, ¿cuál es el rango de temperatura en el que deben mantenerse la mayoría de las vacunas dentro de la cadena de frío?', '+2°C a +8°C', '-15°C a -25°C', '0°C a +2°C', '+10°C a +15°C', 'A', 'El manual establece que todas las vacunas deben mantenerse estrictamente dentro del rango de temperatura recomendada de +2°C a +8°C, dado que la mayoría de biológicos son sensibles tanto a la luz como a las temperaturas extremas. Referencia: Capítulo 3. Cadena de frío. 3.5 Conservación de las vacunas. Página 50.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('1f836638-d534-5920-a28a-8ba172cb9cb9', 'Según el manual, ¿en qué rango de temperatura operan las cámaras de congelación del Banco Nacional de Vacunas (BNV)?', '+2°C a +8°C', '-15°C a -25°C', '-25°C a -80°C', '0°C a -5°C', 'B', 'El manual indica que la infraestructura del BNV cuenta con cámaras frías que mantienen temperaturas controladas entre +2°C y +8°C, así como con cámaras de congelación que operan entre -15°C y -25°C, y ultracongeladores considerados en rangos de -25 a -80°C. Referencia: Capítulo 3. Cadena de frío. 3.3.1 Nivel nacional. Página 41.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('7736cadf-5b01-5d5b-92b9-c50a188f36d8', 'Según el manual, ¿cuál de las siguientes vacunas NUNCA debe congelarse?', 'BCG', 'Fiebre amarilla', 'Rotavirus (líquido y liofilizado)', 'SRP', 'C', 'El manual lista explícitamente entre las vacunas que NO se deben congelar: rotavirus (líquido y liofilizado), neumococo, pentavalente y hexavalente, DPT/DTPa y sus combinaciones (Tdap, Td), hepatitis A y B, Hib líquido, VPH, IPV e influenza. Referencia: Capítulo 3. Cadena de frío. 3.5 Conservación de las vacunas. Página 51.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('e1874f4f-0f98-5288-b991-1f1e8a934079', 'Según el manual, ¿qué procedimiento se utiliza para verificar si una vacuna ha sido expuesta a congelación?', 'El monitor de vial de vacuna (MVV)', 'El termómetro de máxima/mínima', 'La prueba de Coombs', 'La prueba de agitación', 'D', 'El manual describe la prueba de agitación como el procedimiento utilizado para verificar si una vacuna ha sido expuesta a congelación, comparando visualmente un frasco sospechoso con otro del mismo lote congelado intencionalmente como control, agitando ambos y observando la velocidad de sedimentación. Referencia: Capítulo 3. Cadena de frío. 3.5 Conservación de las vacunas. Página 52.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('7698462a-3a4d-5368-8188-4298f35835df', 'Caso clínico: En un establecimiento de salud tipo A ocurre un corte de energía eléctrica que afecta a la refrigeradora doméstica donde se almacenan las vacunas. Según el manual, si transcurren tres horas sin restablecerse el servicio eléctrico, ¿qué se debe hacer?', 'Preparar termos o cajas frías con paquetes fríos previamente acondicionados y trasladar las vacunas, sellando con fecha y hora', 'Abrir la refrigeradora de inmediato para verificar el estado de las vacunas', 'Desechar todas las vacunas de inmediato sin más evaluación', 'Esperar indefinidamente sin tomar ninguna acción', 'A', 'El manual indica que si transcurridas tres horas no se ha restablecido el servicio eléctrico, se debe preparar termos o cajas frías con paquetes fríos previamente acondicionados, registrar en la bitácora la fecha y hora, trasladar las vacunas a estos dispositivos y sellarlos con la fecha y hora correspondiente. Referencia: Capítulo 3. Cadena de frío. 3.9 Ruptura de la cadena de frío. Página 74-75.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('9341d794-51ae-5b16-a393-19a5fda40fc0', 'Según el manual, ¿a qué entidad corresponde el análisis técnico de los eventos de ruptura de cadena de frío y la determinación de la viabilidad o descarte de las vacunas afectadas?', 'A la Dirección Nacional de Hospitales', 'A la Agencia Nacional de Regulación, Control y Vigilancia Sanitaria (ARCSA)', 'Al director del establecimiento de salud, de forma unilateral', 'Al fabricante de la vacuna exclusivamente, sin intervención nacional', 'B', 'El manual establece que el análisis técnico de los eventos de ruptura de cadena de frío y la determinación de la viabilidad o descarte de las vacunas afectadas le corresponde a la Agencia Nacional de Regulación, Control y Vigilancia Sanitaria (ARCSA), evaluando cada caso con base en las condiciones específicas del incidente. Referencia: Capítulo 3. Cadena de frío. 3.9 Ruptura de la cadena de frío. Página 76.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('d9cd22b5-91b8-5e1e-aed4-0ee79a9b4d9f', 'Según el manual, ¿en qué plazo máximo debe comunicar la entidad desconcentrada correspondiente el evento de ruptura de cadena de frío a la ARCSA, a partir de la detección de la irregularidad?', '24 horas', '15 días', '5 días', '30 días', 'C', 'El manual establece que la entidad desconcentrada respectiva debe comunicar el evento a la ARCSA en un plazo máximo de cinco (5) días contados a partir de la detección de la irregularidad. Referencia: Capítulo 3. Cadena de frío. 3.9 Ruptura de la cadena de frío. Página 76.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('9e6475bf-10e0-53c3-bdb3-164299a57f50', 'Caso clínico: Un vial multidosis líquido de vacuna hexavalente fue abierto hace 20 días, se ha conservado entre +2°C y +8°C, su fecha de caducidad sigue vigente y se ha manipulado con técnica aséptica, registrando la fecha y hora de apertura. Según la política del frasco abierto del manual, ¿puede seguir utilizándose este vial?', 'No, los viales multidosis solo pueden usarse el mismo día de su apertura', 'No, todos los viales multidosis deben descartarse a las 6 horas de abiertos sin excepción', 'Sí, pero solo si se usa dentro de las primeras 6 horas de cada jornada, sin límite de días', 'Sí, las vacunas multidosis líquidas pueden utilizarse hasta 28 días después de su apertura si se cumplen las condiciones de conservación, asepsia y registro', 'D', 'Según la política de frasco abierto (PFO) del manual, las vacunas multidosis líquidas —entre ellas la hexavalente— pueden utilizarse hasta 28 días después de su apertura, siempre que la fecha de caducidad esté vigente, se mantengan entre +2°C y +8°C, se manipulen con técnica aséptica y se registre la fecha y hora de apertura. Referencia: Capítulo 3. Cadena de frío. 3.10 Política del frasco abierto. Tabla 9. Página 78-79.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('7b6fb51f-54bf-54de-9f5a-68d5a8c0e69b', 'Caso clínico: Se abre un vial de vacuna BCG reconstituida al inicio de la jornada de vacunación en un centro de salud. Según la política del frasco abierto del manual, ¿hasta cuándo puede utilizarse este vial?', 'Máximo seis horas o al finalizar la jornada de vacunación, lo que ocurra primero', 'Hasta 28 días después de su apertura', 'Hasta la fecha de caducidad impresa en el empaque, sin otra restricción', 'Indefinidamente si se refrigera correctamente', 'A', 'El manual especifica que las vacunas liofilizadas o que requieren reconstitución, como la BCG, sarampión, SRP, fiebre amarilla e Hib, solo pueden utilizarse durante la jornada de vacunación y deben descartarse al finalizarla o a las seis horas, lo que ocurra primero. Referencia: Capítulo 3. Cadena de frío. 3.10 Política del frasco abierto. Tabla 9. Página 79.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('9797d3dc-ab41-58ed-88c1-2a9b75717173', 'Según el manual, ¿qué porcentaje de la capacidad interna total de un refrigerador de cadena de frío corresponde al espacio útil real para almacenar vacunas?', '25%', '50%', '75%', '100%', 'B', 'El manual señala que, según normas técnicas, el espacio útil corresponde al 50% de la capacidad interna total del equipo; el otro 50% debe permanecer libre para permitir la circulación de aire frío, garantizar el acceso adecuado a las vacunas y reservar zonas para elementos estabilizadores. Referencia: Capítulo 3. Cadena de frío. 3.4 Capacidad de almacenamiento de vacunas. Página 49.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('cc72a08a-7d43-59aa-a933-33a2b10c99c5', 'Según el manual, ¿puede almacenarse la vacuna antirrábica de uso animal en las mismas cámaras frías que las vacunas de uso humano?', 'No, nunca puede compartir espacio con vacunas humanas', 'Sí, sin ninguna condición especial', 'Sí, siempre que permanezca en su empaque terciario, debidamente rotulada y claramente separada', 'No existe vacuna antirrábica de uso animal en el sistema de cadena de frío', 'C', 'El manual indica que la vacuna antirrábica de uso animal puede almacenarse en las mismas cámaras o cuartos fríos que las vacunas de uso humano, siempre que permanezca en su empaque terciario, debidamente rotulada y claramente separada. Referencia: Capítulo 3. Cadena de frío. 3.5 Conservación de las vacunas. Página 53.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('40e5ed7d-b1a4-5585-8b04-66311105a975', 'Según el manual, ¿qué está estrictamente prohibido almacenar dentro de los refrigeradores o cámaras destinados a la conservación de vacunas?', 'Paquetes fríos', 'Termómetros de control', 'Diluyentes del mismo fabricante', 'Alimentos, bebidas u otros medicamentos como insulina o antibióticos', 'D', 'El manual establece que está estrictamente prohibido almacenar alimentos, bebidas u otros medicamentos como insulina o antibióticos dentro de los refrigeradores o cámaras destinados a la conservación de vacunas, ya que compromete la integridad de la cadena de frío y aumenta el riesgo de contaminación cruzada. Referencia: Capítulo 3. Cadena de frío. 3.5 Conservación de las vacunas. Página 53.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('8095cd3f-44b5-5c7d-8cd0-2f602237b739', 'Según el manual, ¿cuál es el tiempo aproximado en que la vacuna triple vírica (SRP) debe administrarse tras su reconstitución?', 'Dentro de los 30 minutos posteriores a su reconstitución', 'Dentro de las 24 horas', 'Dentro de los 7 días', 'No existe límite de tiempo tras la reconstitución', 'A', 'El manual indica que las vacunas liofilizadas requieren reconstitución inmediata con el diluyente específico y su uso dentro del tiempo indicado; específicamente, la vacuna triple vírica debe administrarse en los 30 minutos posteriores a su reconstitución, mientras que otras vacunas liofilizadas conservan su eficacia hasta por 8 horas según recomendaciones del fabricante. Referencia: Capítulo 3. Cadena de frío. 3.5 Conservación de las vacunas. Página 50.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('0718b3fc-f4c2-5af1-b554-0dbe90819e67', 'Según el manual, ¿cuánto debe durar el lavado de manos con agua y jabón en las áreas de vacunación para garantizar su efectividad?', '5 a 10 segundos', '40 a 60 segundos', '5 minutos', 'No se especifica un tiempo', 'B', 'El manual indica que el lavado de manos debe durar entre 40 y 60 segundos para garantizar su efectividad en las áreas de vacunación, como parte de las medidas de higiene esenciales. Referencia: Capítulo 4. Procedimientos generales para la vacunación. Página 83.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('e3906496-aeda-5b74-848b-815467deaf69', 'Según el modelo de los ''cinco momentos para la higiene de las manos'' descrito en el manual, ¿en cuál de los siguientes momentos se debe realizar higiene de manos?', 'Únicamente al finalizar toda la jornada laboral', 'Solo si se percibe suciedad visible en las manos', 'Antes de tener contacto directo con el usuario, por ejemplo, antes de administrar una vacuna', 'Una sola vez por cada diez usuarios atendidos', 'C', 'El manual describe los cinco momentos de higiene de manos, siendo el primero: antes de tener contacto directo con el usuario, por ejemplo, al saludar con un apretón de manos, acariciar a un niño o niña, ayudar a una persona a moverse o antes de administrar una vacuna. Referencia: Capítulo 4. Procedimientos generales para la vacunación. Higiene de manos. Página 83.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('236c6d35-84c2-5787-92dd-257c086d3fdb', 'Caso clínico: Un padre lleva a su hijo a vacunarse, pero no cuenta con el carné de vacunación y desconoce el estado vacunal del menor. Según el manual, ¿cuál es la conducta recomendada en este caso?', 'No vacunar hasta que se presente el carné físico', 'Aplicar únicamente la vacuna que el padre recuerde', 'Referir al menor a otro establecimiento de salud sin más acción', 'Iniciar el esquema de vacunación correspondiente para la edad del menor', 'D', 'El manual establece que si no hay registros o el cuidador desconoce el estado de vacunación del menor, debe iniciarse el esquema de vacunación correspondiente para la edad, como parte de la personalización y seguridad en el proceso de vacunación. Referencia: Capítulo 4. Procedimientos generales para la vacunación. Personalización y seguridad en el proceso de vacunación. Página 87.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('065fed5b-4713-5e07-a90a-ba6b8734f08f', 'Según el manual, dentro de los ''7 correctos'' de la vacunación, ¿qué corresponde verificar en el ''sexto correcto''?', 'Las condiciones correctas del biológico: buen estado, fecha de caducidad y estado del indicador MVV', 'La identidad del usuario', 'La edad del usuario', 'El registro de la dosis aplicada', 'A', 'El manual describe el sexto correcto como ''condiciones correctas del biológico'', que implica verificar que la vacuna esté en buen estado, su fecha de caducidad y el estado del indicador MVV (monitor de vial de vacuna). Referencia: Capítulo 4. Procedimientos generales para la vacunación. Actividades previas a la vacunación. Página 85-86.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('25dbca65-5f9b-5157-9dab-eaffef8408f7', 'Según el manual, después de aplicar una vacuna, ¿cuánto tiempo mínimo se debe mantener al usuario en observación si no presenta antecedentes de alergias?', '5 minutos', '15 minutos', '1 hora', 'No se requiere observación', 'B', 'El manual indica que después de aplicar la vacuna se debe mantener al usuario en observación durante al menos 15 minutos si no presenta antecedentes de alergias; en caso de contar con antecedentes alérgicos, el tiempo de observación debe extenderse a más de 30 minutos. Referencia: Capítulo 4. Procedimientos generales para la vacunación. Actividades posteriores a la vacunación. Página 89.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('33722b24-dae2-5693-b5e5-f1e45ab0f163', 'Según el manual, ¿qué debe hacerse si la aplicación de una vacuna se interrumpe y se ha administrado menos de la mitad de la dosis?', 'Considerar la dosis como completa y no repetirla', 'Esperar una semana para repetir la dosis', 'Debe repetirse la aplicación completa de forma inmediata', 'Administrar solo la mitad restante en otro sitio anatómico', 'C', 'El manual establece que si la aplicación se interrumpe y se ha administrado menos de la mitad de la dosis, debe repetirse la aplicación completa de forma inmediata. Referencia: Capítulo 4. Procedimientos generales para la vacunación. Actividades durante la vacunación. Página 89.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('47c154b2-cd35-5239-997c-59f68d439f63', 'Según el manual, ¿en qué ángulo se introduce la aguja para la administración intradérmica, como en el caso de la vacuna BCG?', '45°', '60°', '90°', '15°', 'D', 'El manual indica que en la administración intradérmica la aguja se introduce en la piel formando un ángulo de 15° con respecto a su superficie, como ocurre con la vacuna BCG aplicada en la región deltoidea derecha. Referencia: Capítulo 5. Vías de administración. 5.2 Administración intradérmica. Página 92.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('2770dcfb-ac5d-5fe0-8d1d-f98f2605fac9', 'Según el manual, ¿en qué ángulo se administra una inyección subcutánea o hipodérmica?', '45°', '15°', '90°', '180°', 'A', 'El manual indica que para aplicar una inyección subcutánea se debe tomar un pliegue de piel entre los dedos y luego insertar la aguja con una inclinación de 45 grados. Referencia: Capítulo 5. Vías de administración. 5.3 Administración subcutánea o hipodérmica. Página 92.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('66e2f620-fd8f-5248-a5a0-2b16d9b850ef', 'Según el manual, ¿por qué se debe evitar la región glútea para la administración intramuscular de vacunas?', 'Porque no existe músculo en esa zona', 'Por el riesgo de infiltración en el tejido adiposo o subcutáneo, mayor acumulación de grasa (especialmente en mujeres) y riesgo de afectar el nervio ciático o causar necrosis', 'Porque está reservada exclusivamente para la administración de insulina', 'Porque el volumen de la dosis no cabe en esa región', 'B', 'El manual explica que se debe evitar la región glútea para vacunas debido al riesgo de infiltración en el tejido adiposo o subcutáneo (lo cual puede comprometer la eficacia inmunológica), y que la mayor acumulación de grasa en esta zona en mujeres incrementa la probabilidad de afectar el nervio ciático o causar necrosis. Referencia: Capítulo 5. Vías de administración. 5.4 Administración intramuscular. Página 93.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('993dae9a-9dae-5fe5-8240-c9b335e2b670', 'Caso clínico: Un niño de 15 meses va a recibir una vacuna por vía intramuscular. Según el manual, ¿cuál es el sitio anatómico preferido para la administración intramuscular en usuarios menores de 3 años?', 'Región deltoidea', 'Región glútea', 'Músculo vasto externo, en el tercio medio de la cara lateral del muslo', 'Región dorsal', 'C', 'El manual indica que en los usuarios menores de 3 años, el sitio preferido para la administración intramuscular es el músculo vasto externo, ubicado en el tercio medio de la cara lateral del muslo, por ser una región segura al estar libre de vasos sanguíneos o nervios importantes. Referencia: Capítulo 5. Vías de administración. 5.4 Administración intramuscular. Página 94-95.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('647c5ea3-9a24-5ad2-bf49-dde980c2be82', 'Según el manual, ¿a partir de qué edad se recomienda utilizar el músculo deltoides para la administración intramuscular, si el desarrollo muscular lo permite?', 'Desde el nacimiento', 'A partir de los 12 años', 'Únicamente en adultos', 'A partir de los 3 años', 'D', 'El manual indica que a partir de los 3 años, si el desarrollo muscular lo permite, se utiliza el músculo deltoides; en menores de 12 meses no se recomienda debido a su insuficiente desarrollo. Referencia: Capítulo 5. Vías de administración. 5.4 Administración intramuscular. Página 96.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('5c9fd8cb-4142-5194-9a18-45b1975f89da', 'Según el manual, ¿es necesario aspirar antes de inyectar una vacuna por vía intramuscular, subcutánea o intradérmica?', 'No, no se requiere aspiración previa en ninguna de las tres vías', 'Sí, siempre es obligatorio en las tres vías', 'Solo es obligatorio en la vía intramuscular', 'Solo es obligatorio en menores de un año', 'A', 'El manual establece explícitamente que no se requiere aspiración previa en ninguna de las vías (intramuscular, subcutánea o intradérmica), siendo más importante utilizar el tamaño de aguja correcto y elegir apropiadamente el sitio anatómico. Referencia: Capítulo 5. Vías de administración. 5.4 Administración intramuscular. Página 94.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('2dfdf983-1a1c-5fb0-8f4c-04cc2772b76f', 'Según el manual, ¿por qué NO se debe aplicar la vacuna BCG en el mismo brazo donde se ha administrado otra vacuna?', 'Porque reduce la absorción del componente vacunal', 'Por riesgo de linfadenitis regional, restricción que debe mantenerse por al menos tres meses', 'Porque produce dolor excesivo al usuario', 'No existe ninguna restricción sobre este aspecto', 'B', 'El manual indica que la vacuna BCG no debe aplicarse en el mismo brazo donde se ha administrado otra vacuna, debido al riesgo de linfadenitis regional, restricción que debe mantenerse por al menos tres meses tras la aplicación de la BCG. Referencia: Capítulo 6. Aplicación simultánea de vacunas e intervalos de aplicación. 6.6 Sitios de aplicación para vacunas administradas simultáneamente. Página 105.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('7ae6a11f-eadb-522d-a671-8ec9c13a204b', 'Según el manual, ¿cuál es la distancia mínima que se debe mantener entre los puntos de punción cuando dos vacunas se aplican en la misma región anatómica?', '0,5 cm', '1 cm', '2,5 cm', '5 cm', 'C', 'El manual indica que cuando dos vacunas deben aplicarse en una misma región anatómica, es indispensable mantener una distancia mínima de 2,5 cm entre los puntos de punción a fin de evitar reacciones locales superpuestas. Referencia: Capítulo 6. Aplicación simultánea de vacunas e intervalos de aplicación. 6.6 Sitios de aplicación. Página 105.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('1af4d759-be9c-546e-b8b3-3f4c2ba11915', 'Según el manual, ¿cuál es el intervalo mínimo que debe respetarse entre dos vacunas de antígenos vivos atenuados por vía inyectable, cuando no se aplican simultáneamente?', '1 semana', '2 semanas', '3 meses', '4 semanas (28 días)', 'D', 'El manual establece que las vacunas inyectables con virus vivos atenuados (SRP, SR, varicela, fiebre amarilla, BCG) pueden administrarse de manera conjunta en distintos sitios anatómicos; si no se aplican en el mismo momento, se debe respetar un intervalo mínimo de cuatro semanas entre dos vacunas vivas atenuadas por vía parenteral. Referencia: Capítulo 6. Aplicación simultánea de vacunas e intervalos de aplicación. 6.3 Intervalo entre las dosis de diferentes vacunas. Página 101.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('dcac4f0e-8373-578b-8964-8e17e990e8e3', 'Caso clínico: Un niño recibe la vacuna oral contra rotavirus y, en la misma consulta, se le indica la vacuna oral bOPV. Según el manual, ¿es necesario respetar algún intervalo entre estas dos vacunas orales de antígenos vivos atenuados?', 'No; las vacunas vivas atenuadas de administración oral pueden administrarse simultáneamente o en cualquier intervalo entre ellas', 'Sí, se debe esperar 4 semanas entre ambas', 'Sí, se debe esperar al menos 1 semana', 'No pueden coadministrarse bajo ninguna circunstancia', 'A', 'El manual aclara que la recomendación del intervalo de 4 semanas entre vacunas vivas atenuadas no se aplica a las vacunas vivas administradas por vía oral (rotavirus, poliomielitis oral y fiebre tifoidea), las cuales pueden administrarse en cualquier momento, tanto entre sí como en combinación con otras vacunas. Referencia: Capítulo 6. Aplicación simultánea de vacunas e intervalos de aplicación. 6.3 Intervalo entre las dosis de diferentes vacunas. Tabla 11. Página 102.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('91860b4b-884a-55c3-b544-e6bbd80b89c7', 'Caso clínico: Una mujer puérpera recibió globulina anti-Rho (D) y requiere la vacuna SR. Según el manual, ¿se debe postergar la aplicación de la vacuna SR en esta paciente?', 'Sí, siempre se debe postergar tres meses', 'No se justifica retrasar la vacunación con SR en mujeres puérperas que hayan recibido globulina anti-Rho (D), debido a la baja concentración de inmunoglobulinas de este producto', 'Sí, se debe postergar indefinidamente', 'No se puede administrar SR después del parto bajo ninguna circunstancia', 'B', 'El manual indica que, en el caso específico de la cepa RA27/3 de la vacuna contra la rubéola, su eficacia no se ve comprometida por la administración de globulina anti-Rho (D) en mujeres en el período posparto, ya que la concentración de inmunoglobulinas en este producto es baja, por lo que no se justifica retrasar la vacunación con SR en estas pacientes. Referencia: Capítulo 6. Aplicación simultánea de vacunas e intervalos de aplicación. 6.4 Intervalos entre vacunas vivas atenuadas y productos con anticuerpos. Página 104.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('4641e132-b28b-54f5-967a-5aaa36c9ecd9', 'Según el manual, ¿cómo debe considerarse una dosis de vacuna administrada antes de cumplir el intervalo mínimo recomendado entre dosis del mismo inmunógeno?', 'Válida sin ninguna condición', 'Válida solo si el paciente es menor de un año', 'Nula, salvo que se administre dentro de un margen de uno a cuatro días previos al intervalo mínimo (con excepciones específicas)', 'Siempre debe considerarse válida si el paciente no presentó reacciones adversas', 'C', 'El manual indica que las dosis aplicadas antes de cumplir el intervalo mínimo deben considerarse nulas, aunque se considerará válida la dosis si esta se administra dentro de un margen de uno a cuatro días previos al intervalo mínimo recomendado, con excepción de los esquemas que incluyan las vacunas antirrábica y antitifoídica. Referencia: Capítulo 6. Aplicación simultánea de vacunas e intervalos de aplicación. 6.2 Intervalo entre las dosis de un mismo inmunógeno. Página 100-101.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('0ff7c4a0-8c70-5aca-ad65-7247d3872c68', 'Según el manual, ¿qué se debe hacer si se administra inadvertidamente una vacuna caducada?', 'No es necesario repetir la dosis si el paciente no presenta síntomas', 'Se debe esperar un año para repetir la dosis, independientemente del tipo de vacuna', 'Nunca se puede repetir una dosis de una vacuna caducada', 'La dosis se invalida y es necesario repetirla; las inactivadas se repiten tan pronto sea posible y las vivas atenuadas tras un intervalo de al menos 28 días', 'D', 'El manual indica que la administración inadvertida de una vacuna caducada invalida la dosis, siendo necesaria su repetición; las vacunas inactivadas deben administrarse nuevamente tan pronto como sea factible, mientras que las vacunas vivas atenuadas deben ser reaplicadas después de un intervalo de al menos 28 días. Referencia: Capítulo 6. Aplicación simultánea de vacunas e intervalos de aplicación. 6.2 Intervalo entre las dosis de un mismo inmunógeno. Página 101.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('80426f18-a69c-550c-a4fa-69f6e55a9721', 'Según el manual, ¿qué recomienda hacer si los intervalos entre dosis de un esquema exceden lo recomendado, por interrupciones en la serie vacunal?', 'No es necesario reiniciar el esquema; se debe completar el esquema establecido, ya que los intervalos prolongados no comprometen la respuesta inmunológica', 'Reiniciar todo el esquema desde el principio', 'Descartar por completo la posibilidad de completar el esquema', 'Aplicar el doble de dosis para compensar el retraso', 'A', 'El manual indica que en situaciones donde los intervalos entre dosis excedan lo recomendado, ya sea por interrupciones en la serie vacunal, indicaciones médicas o circunstancias excepcionales, no será necesario reiniciar el esquema; es fundamental completar el esquema establecido ya que los intervalos prolongados no comprometen la respuesta inmunológica. Referencia: Capítulo 6. Aplicación simultánea de vacunas e intervalos de aplicación. 6.2 Intervalo entre las dosis de un mismo inmunógeno. Página 101.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('7afd3ab4-258e-5602-8cdc-81357f072f39', 'Según el manual, ¿durante cuánto tiempo aproximado puede prolongarse la interferencia inmunológica en las vacunas contra sarampión y rubéola tras la administración de un producto con anticuerpos como la inmunoglobulina?', '1 semana', 'Al menos tres meses', '1 año completo', 'No existe interferencia entre estos productos', 'B', 'El manual señala que este efecto de interferencia puede prolongarse por al menos tres meses tras la administración del producto con anticuerpos, siendo especialmente relevante en el caso de las vacunas contra el sarampión y la rubéola. Referencia: Capítulo 6. Aplicación simultánea de vacunas e intervalos de aplicación. 6.4 Intervalos entre vacunas vivas atenuadas y productos con anticuerpos. Página 103.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('7b57a8d8-b0b2-575a-9a68-9753c021f41a', 'Caso clínico: Un recién nacido se encuentra en las primeras 24 horas de vida en un hospital de segundo nivel. Según la Tabla 15 del esquema nacional de vacunación, ¿qué vacunas corresponde administrar en este momento?', 'Rotavirus y Hexavalente', 'SRP y Varicela', 'BCG y HB CERO', 'bOPV y Neumococo', 'C', 'Según la Tabla 15 del esquema nacional, en las primeras 24 horas de nacido se administra la vacuna BCG (dosis única hasta los 364 días) y la HB CERO, dosis de hepatitis B en las primeras 24 horas de vida. Referencia: Capítulo 8. Esquema Nacional de Vacunación. Tabla 15. Esquema de Vacunación del Ecuador. Página 116.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('b8d9d0d7-8770-5223-b992-918fb7678e77', 'Caso clínico: Un lactante de 2 meses acude a su primera cita de vacunación regular. Según la Tabla 15 del esquema nacional, ¿qué vacunas corresponde administrar a esta edad?', 'BCG, HB CERO', 'bOPV, SRP', 'FA, Varicela', 'Rotavirus, Hexavalente, Neumococo', 'D', 'Según la Tabla 15, a los 2 meses de edad corresponde administrar Rotavirus, Hexavalente y Neumococo, esquema que se repite a los 4 meses, y a los 6 meses se agrega bOPV junto con Hexavalente y Neumococo. Referencia: Capítulo 8. Esquema Nacional de Vacunación. Tabla 15. Esquema de Vacunación del Ecuador. Página 116.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('ca85dbc9-f613-586b-b506-521589afd9d2', 'Según la Tabla 15 del esquema nacional, ¿en qué grupo etario se indica la vacuna contra el VPH?', 'A los 9 años', 'A los 5 años', 'A los 15 años', 'En menores de un año', 'A', 'Según la Tabla 15 del esquema nacional de vacunación, la vacuna contra el VPH se administra a los 9 años de edad, dentro del grupo de adolescencia. Referencia: Capítulo 8. Esquema Nacional de Vacunación. Tabla 15. Esquema de Vacunación del Ecuador. Página 117.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('4a1fa87b-2517-55fd-b29e-018aa4dd1c64', 'Caso clínico: Una gestante acude a control prenatal en su segundo trimestre. Según la Tabla 15 del esquema nacional, ¿qué vacunas se contemplan para las embarazadas según antecedente vacunal?', 'Únicamente BCG', 'dT, HB, Tdap y VSR', 'Únicamente SRP', 'Rotavirus y Hexavalente', 'B', 'Según la Tabla 15 del esquema nacional, las embarazadas reciben dT (según antecedente vacunal), HB (según antecedente vacunal), Tdap y VSR, dentro del grupo de adultos y vacunación en grupos de riesgo. Referencia: Capítulo 8. Esquema Nacional de Vacunación. Tabla 15. Esquema de Vacunación del Ecuador. Página 117.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('d9cc16b6-5a56-5951-a4e7-76f13f9cd3f7', 'Según la Tabla 15 del esquema nacional, ¿a qué edad se administra la segunda dosis de SRP?', '12 meses', '15 meses', '18 meses', '5 años', 'C', 'Según la Tabla 15, la primera dosis de SRP se administra a los 12 meses (junto con FA a esa misma edad) y la segunda dosis (SRP 2) se administra a los 18 meses, junto con hexavalente y bOPV. Referencia: Capítulo 8. Esquema Nacional de Vacunación. Tabla 15. Esquema de Vacunación del Ecuador. Página 117.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('36755cc6-37b4-504e-aef4-821e5a2aa775', 'Según la Tabla 15 del esquema nacional, ¿qué grupo poblacional debe recibir la vacuna contra la influenza estacional en dos dosis con intervalo de 28 días?', 'Adultos mayores de 65 años exclusivamente', 'Personal de salud exclusivamente', 'Embarazadas exclusivamente', 'Niños de 6 a 11 meses', 'D', 'Según la Tabla 15, los niños de 6-11 meses reciben la vacuna contra influenza estacional en 2 dosis con intervalo de 28 días; posteriormente, de 12 a 59 meses reciben la vacuna de forma anual. Referencia: Capítulo 8. Esquema Nacional de Vacunación. Tabla 15. Esquema de Vacunación del Ecuador. Página 116.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('49acda02-6b44-565f-802a-a58ca4a5dca8', 'Según la Tabla 15 del esquema nacional, ¿en qué momento se contempla el refuerzo con DPT en la niñez, según el esquema regular?', 'A los 5 años, junto con bOPV y varicela', 'A los 12 meses', 'A los 9 años', 'A los 15 años', 'A', 'Según la Tabla 15 del esquema nacional, a los 5 años, dentro del grupo etario de niñez, se administran DPT, bOPV y varicela. Referencia: Capítulo 8. Esquema Nacional de Vacunación. Tabla 15. Esquema de Vacunación del Ecuador. Página 117.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('523575f7-0532-575b-bd55-2aa5ef082f1c', 'Según el manual, ¿qué caracteriza a la ''vacunación regular'' dentro del esquema nacional?', 'Es la aplicación exclusiva en campañas extraordinarias de emergencia', 'Es la aplicación sistemática de las vacunas incluidas en el esquema nacional, que puede realizarse de manera oportuna, anticipada o tardía según edad y antecedentes', 'Es la aplicación de vacunas únicamente en el sector privado', 'Es la aplicación de una única dosis de refuerzo cada 10 años exclusivamente', 'B', 'El manual define a la vacunación regular como la aplicación sistemática de las vacunas incluidas en el esquema nacional, que puede realizarse en cualquier momento del ciclo vacunal, tanto de manera oportuna, anticipada o tardía, según la edad y antecedentes de vacunación. Referencia: Capítulo 8. Esquema Nacional de Vacunación. Página 116.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('0b317527-5ec9-5af4-a4fa-32d102ded26c', 'Caso clínico: Un recién nacido de 24 horas de vida presenta buen estado general y no hay antecedentes de contraindicaciones. Según el manual, ¿cuál es el sitio anatómico y el ángulo de aplicación de la vacuna BCG?', 'Cara anterolateral del muslo, ángulo intramuscular de 90°', 'Región glútea, ángulo subcutáneo de 45°', 'Región deltoidea derecha, ángulo intradérmico de 15°', 'Región deltoidea izquierda, vía oral', 'C', 'El manual especifica que la vacuna BCG se administra por vía intradérmica, con un ángulo de 15°, en la región deltoidea derecha, donde se produce una pápula que desaparece en 15 a 30 minutos. Referencia: Capítulo 9. Enfermedades y vacunas. 9.1.1 Vacuna BCG. Tabla 17. Página 121.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('27257ea3-c057-5b38-a0a2-69945a6b8974', 'Según el manual, ¿qué medicamento tuberculostático NO inactiva el bacilo vacunal de la BCG, a diferencia de los demás fármacos de este grupo?', 'Isoniazida', 'Rifampicina', 'Etambutol', 'Pirazinamida', 'D', 'El manual señala que los medicamentos tuberculostáticos pueden inactivar el bacilo vacunal de la BCG, exceptuando la pirazinamida, que no presenta este efecto. Referencia: Capítulo 9. Enfermedades y vacunas. 9.1.1 Vacuna BCG. Tabla 17. Página 121.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('80a0f568-883b-5eba-8470-e14154315751', 'Caso clínico: Un recién nacido pretérmino de 33 semanas de gestación, con peso adecuado para su edad gestacional, se encuentra clínicamente estable. Según el manual, ¿la vacuna BCG debe aplicarse en este paciente?', 'Sí; en prematuros de 32-36 semanas la vacunación es segura y eficaz, y reduce la mortalidad en niños con bajo peso al nacer', 'No, está formalmente contraindicada en todo prematuro', 'Solo si el peso al nacer supera los 4.000 g', 'Solo después de los 6 meses de vida', 'A', 'El manual indica que en prematuros de 32–36 semanas la vacunación con BCG es segura y eficaz y reduce la mortalidad en los niños con bajo peso al nacer, aunque no hay contraindicaciones, la aplicación intradérmica puede verse dificultada por las características de la piel del niño pretérmino. Referencia: Capítulo 9. Enfermedades y vacunas. 9.1.1 Vacuna BCG. Tabla 18. Página 123.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('5f40a284-ed06-565b-866c-3c43c9869979', 'Caso clínico: Un recién nacido hijo de madre HBsAg positivo requiere protección inmediata contra la hepatitis B. Según el manual, ¿qué se debe hacer en este caso?', 'Aplicar únicamente la vacuna HB0 sin inmunoglobulina', 'Aplicar simultáneamente HB0 e inmunoglobulina antihepatitis B (IgHB) en las primeras 12 horas de vida (no más de 24 h), en sitios anatómicos distintos', 'Esperar hasta los 6 meses de vida para iniciar cualquier profilaxis', 'Administrar solo inmunoglobulina, sin vacuna', 'B', 'El manual indica que en recién nacidos de madre HBsAg positivo se debe aplicar simultáneamente HB0 e IgHB en las primeras 12 horas de vida (no más de 24 h), en sitios anatómicos distintos (por ejemplo, muslos opuestos). Referencia: Capítulo 9. Enfermedades y vacunas. 9.2.2 Inmunoglobulina humana antihepatitis B. Tabla 22. Página 129.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('995fc58d-de82-5378-ada5-849a0b0d9f6b', 'Según el manual, ¿cuál es el esquema de vacunación contra hepatitis B recomendado para pacientes en hemodiálisis crónica o con inmunosupresión?', 'Dos dosis estándar (0 y 1 mes)', 'Dosis única de por vida', 'Cuatro dosis de 40 mcg en los meses 0, 1, 2 y 6, contando desde la primera dosis', 'El mismo esquema que un recién nacido sano, sin modificaciones', 'C', 'El manual indica que para las personas con hemodiálisis crónica o con inmunosupresión, el esquema de vacunación contra hepatitis B es de cuatro dosis (40 mcg) en los meses 0, 1, 2 y 6, contando desde la fecha de la primera dosis. Referencia: Capítulo 9. Enfermedades y vacunas. 9.2.1 Vacuna contra la hepatitis B. Página 127.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('0a106632-8e31-5c2d-96cf-94b4d9935bfe', 'Según el manual, ¿cuál es el esquema de vacunación oral contra rotavirus dentro del esquema nacional, en términos de las edades de administración?', '2, 4 y 6 meses', '12 y 18 meses', '6 meses únicamente', '2 y 4 meses', 'D', 'Según la Tabla 15 del esquema nacional, la vacuna Rotavirus se administra a los 2 y 4 meses de edad, junto con Hexavalente y Neumococo en cada una de esas visitas. Referencia: Capítulo 8. Esquema Nacional de Vacunación. Tabla 15. Página 116.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('feaa3780-df9c-5c30-a820-b38574c07d92', 'Según el manual, la vacuna DPT (pediátrica) se administra como refuerzo a los 5 años. ¿Cuáles son los tres componentes principales que combina?', 'Toxoide diftérico, toxoide tetánico y Bordetella pertussis de célula entera', 'Antígeno de hepatitis B, toxoide tetánico y Hib', 'Poliovirus inactivado, toxoide diftérico y neumococo', 'Sarampión, rubéola y parotiditis', 'A', 'El manual describe la composición de la vacuna DPT pediátrica como: toxoide diftérico, toxoide tetánico, Bordetella pertussis (célula entera), con fosfato de aluminio y tiomersal. Referencia: Capítulo 9. Enfermedades y vacunas. 9.6.1 Vacunas contra la difteria, tosferina y tétanos. Tabla 30. Página 141.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('67fcc9cb-7176-5a1f-95fa-c4f08c0b5c29', 'Caso clínico: Una gestante de 28 semanas acude a control prenatal y no tiene antecedente de vacunación con Tdap en este embarazo. Según el manual, ¿en qué momento del embarazo se recomienda aplicar la vacuna Tdap?', 'Únicamente en el primer trimestre', 'Desde las 20 semanas de gestación hasta el parto, idealmente entre las 27-36 semanas', 'Solo después del parto', 'No está indicada durante el embarazo', 'B', 'El manual indica que la vacuna Tdap se administra una dosis en cada embarazo desde las 20 semanas de gestación hasta el parto, idealmente desde las 27-36 semanas de gestación, con un intervalo mínimo de un mes con la vacuna dT. Referencia: Capítulo 9. Enfermedades y vacunas. 9.6.2 Vacunas contra la difteria, tosferina (acelular) y tétanos (Tdap). Tabla 32. Página 144.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('d44457f2-72e2-5d59-afb3-80504ec67875', 'Según el manual, ¿qué beneficio se ha demostrado con la administración de la vacuna Tdap durante el embarazo?', 'Elimina completamente el riesgo de parto prematuro', 'Sustituye la necesidad de vacunación infantil contra tosferina', 'Reduce significativamente la mortalidad por tosferina en neonatos menores de 2 meses', 'No aporta ningún beneficio adicional al recién nacido', 'C', 'El manual señala que la administración de Tdap en el embarazo ha demostrado reducir significativamente la mortalidad por tosferina en neonatos menores de 2 meses. Referencia: Capítulo 9. Enfermedades y vacunas. 9.6.2 Vacunas contra la difteria, tosferina (acelular) y tétanos (Tdap). Página 145.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('fd3cb1a2-4356-53fe-a4d8-1004813eaa8f', 'Según el manual, ¿qué componentes incluye la vacuna hexavalente de célula entera del esquema nacional?', 'Únicamente componentes contra sarampión, rubéola y parotiditis', 'Únicamente el componente de neumococo 13-valente', 'Solo toxoide tetánico y diftérico, sin otros componentes', 'Toxoide diftérico, toxoide tetánico, Hib, B. pertussis de célula entera, HBsAg y vacuna inactivada de polio (tipo 1, 2 y 3)', 'D', 'El manual describe la composición de la vacuna hexavalente de célula entera como: toxoide diftérico, toxoide tetánico, Hib, B. pertussis de célula entera, HBsAg y vacuna inactivada de polio (tipos 1, 2 y 3), conjugado a TT. Referencia: Capítulo 9. Enfermedades y vacunas. 9.7.1 Vacuna hexavalente celular. Tabla 37. Página 151.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('8944e3c7-158e-5b2b-8c17-60635b708ba3', 'Según el manual, ¿cuál es el esquema primario de la vacuna hexavalente de célula entera dentro del esquema nacional?', '3 dosis primarias a los 2, 4 y 6 meses, con 1 dosis de refuerzo un año después de la tercera dosis', '2 dosis a los 12 y 18 meses', 'Dosis única al nacer', '5 dosis desde el nacimiento hasta los 6 meses', 'A', 'El manual indica que el esquema de vacunación de la hexavalente de célula entera consiste en 3 dosis primarias (a los 2, 4 y 6 meses) y 1 dosis de refuerzo un año después de la administración de la tercera dosis. Referencia: Capítulo 9. Enfermedades y vacunas. 9.7.1 Vacuna hexavalente celular. Tabla 37. Página 151.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('24e3fd4b-cbc6-5df2-8b4e-d69c10530d10', 'Caso clínico: Un niño con trastorno neurológico progresivo, como espasmos infantiles no controlados, requiere continuar con su esquema de vacunación con componente pertussis. Según el manual, ¿cuál es la conducta recomendada?', 'Administrar la vacuna sin ninguna modificación', 'Posponer la inmunización con componente pertussis hasta la estabilización del cuadro clínico', 'Suspender definitivamente todo el esquema de vacunación', 'Administrar solo la mitad de la dosis habitual', 'B', 'El manual indica que en niños con trastornos neurológicos progresivos (como epilepsia no controlada, encefalopatía progresiva o espasmos infantiles), se debe posponer la inmunización hasta la estabilización del cuadro clínico, como precaución para la vacuna hexavalente y otras con componente pertussis. Referencia: Capítulo 9. Enfermedades y vacunas. 9.7.1 Vacuna hexavalente celular. Tabla 38. Página 152.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('ea6bf0f5-38ff-558c-a121-a177c5e4778c', 'Caso clínico: Un niño de 6 años y 11 meses de edad no tiene ningún antecedente de vacunación contra la poliomielitis. Según el manual, ¿qué combinación de vacunas contra la poliomielitis se recomienda utilizar en el esquema, considerando el mínimo de dosis de IPV previo a la bOPV?', 'Solo dosis orales de bOPV, sin IPV', 'Solo dosis de IPV, sin bOPV', 'Cinco dosis, con un mínimo de dos dosis de IPV previas a la administración de tres dosis de bOPV', 'Una única dosis de bOPV es suficiente', 'C', 'El manual indica que la población infantil debe recibir cinco dosis de vacuna contra la poliomielitis, con un mínimo de dos dosis de vacuna IPV previas a la administración de tres dosis de bOPV, según el esquema detallado en la Tabla 41. Referencia: Capítulo 9. Enfermedades y vacunas. 9.8.1 Vacunas contra el poliovirus bOPV-IPV. Página 155.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('8cb33ae5-986f-56a3-af5c-cd80422764d5', 'Según el manual, ¿cuántas dosis de IPV deben recibir los niños con trastornos de inmunosupresión moderada o severa, y con qué esquema?', 'Solo una dosis de IPV, sin refuerzos', 'Ninguna dosis, están exentos de vacunación antipoliomielítica', 'Solo dosis de bOPV, nunca IPV', 'Cinco dosis de IPV, siguiendo el mismo esquema de manera oportuna', 'D', 'El manual indica que los niños con trastornos de inmunosupresión moderada o severa deben recibir cinco dosis de IPV siguiendo el mismo esquema de manera oportuna, en lugar de recibir bOPV (vacuna de virus vivos atenuados). Referencia: Capítulo 9. Enfermedades y vacunas. 9.8.1 Vacunas contra el poliovirus bOPV-IPV. Página 156.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('67add51a-fcec-5f11-bdb2-8866bfef1290', 'Caso clínico: Un niño de 6 años sin antecedente de vacunación contra sarampión, rubéola y parotiditis acude a consulta. Según el manual, ¿qué vacuna corresponde aplicar y con qué esquema, considerando que la vacuna SRP está indicada en todos los niños menores de siete años?', 'SRP, dos dosis: la primera al contacto y la segunda al mes', 'SR, dosis única, ya que es mayor de 7 años', 'No corresponde ninguna vacunación en este grupo etario', 'Solo la vacuna contra la varicela', 'A', 'El manual indica que la vacuna SRP está indicada en todos los niños menores de siete años como parte del esquema nacional, administrándose en esquema tardío en dos dosis: la primera al contacto y la segunda al mes. Referencia: Capítulo 9. Enfermedades y vacunas. 9.11.1 Vacunas contra el sarampión, rubéola y parotiditis. Página 161.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('03b9a21f-fab4-591f-8116-9e66f9f98bdb', 'Según el manual, ¿qué precaución especial se relaciona con la cepa Leningrad-Zagreb de la vacuna SRP en niños mayores de 7 años?', 'Menor eficacia contra la rubéola', 'Mayor riesgo de meningitis aséptica y orquitis, comparado con la cepa Jerry-Lynn', 'Mayor riesgo de anafilaxia comparado con otras cepas', 'No existe ninguna diferencia entre cepas', 'B', 'El manual señala que existe un mayor riesgo de meningitis aséptica y orquitis con la cepa Leningrad-Zagreb en niños mayores de 7 años, con menor riesgo asociado a la cepa Jerry-Lynn, por lo que se recomienda utilizar la SRP preferentemente en menores de 7 años y priorizar SR en mayores de esa edad. Referencia: Capítulo 9. Enfermedades y vacunas. Tabla 47. Consideraciones de seguridad de la vacuna SRP - SR. Página 162-163.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('77c58edd-c478-5a3a-946e-41fecaa77c90', 'Según el manual, ¿en qué edad y esquema se administra la vacuna conjugada contra el neumococo 13-valente en el esquema nacional?', 'Dosis única a los 12 meses', 'Dos dosis a los 15 y 18 meses', 'Tres dosis a los 2, 4 y 6 meses de edad, desde las 6 semanas de vida', 'Cuatro dosis desde el nacimiento hasta el año', 'C', 'El manual indica que la vacuna neumococo 13-valente está indicada para niños menores de 1 año, administrándose en un esquema de tres dosis a los 2, 4 y 6 meses de edad, desde las 6 semanas de vida. Referencia: Capítulo 9. Enfermedades y vacunas. 9.12.1 Vacuna conjugada contra el neumococo 13-valente. Tabla 49. Página 165-166.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('39d93f0f-8805-5b61-abe4-37bbbec5ce45', 'Según el manual, ¿es posible que un niño que inició su esquema con la vacuna neumococo 13-valente continúe con la 20-valente?', 'No, nunca son intercambiables', 'Solo si han transcurrido 5 años entre dosis', 'Solo en pacientes adultos, nunca en niños', 'Sí, ambas vacunas son intercambiables de acuerdo con las normas técnicas vigentes', 'D', 'El manual indica que la vacuna neumococo 20-valente es intercambiable con la vacuna conjugada 13-valente, de modo que los niños que han iniciado la inmunización con esta última pueden continuar el esquema con la 20-valente, de acuerdo con las normas técnicas vigentes. Referencia: Capítulo 9. Enfermedades y vacunas. 9.12.2 Vacuna conjugada contra el neumococo 20-valente. Página 167-168.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('2ef46eb3-5c13-5aa0-ae6e-f0cd6bc174b2', 'Caso clínico: Una niña de 15 meses va a recibir su primera dosis de vacuna contra la varicela. Según el manual, ¿cuándo corresponde la segunda dosis de esta vacuna en el esquema temprano?', 'A los 5 años de edad', 'A los 18 meses', 'Al mes siguiente', 'No se requiere segunda dosis', 'A', 'El manual indica que en el esquema temprano se recomiendan dos dosis de la vacuna contra la varicela: la primera a los 15-23 meses de vida y la segunda a los 5 años de edad, con un intervalo mínimo de tres meses entre dosis. Referencia: Capítulo 9. Enfermedades y vacunas. 9.13.1 Vacuna contra la varicela. Tabla 54. Página 172.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('a6f68a22-3f41-55b6-8e31-651154906bac', 'Según el manual, ¿qué precaución se debe tener con el uso de salicilatos tras la vacunación contra la varicela en menores de 18 años?', 'No existe ninguna interacción relevante', 'Se debe evitar su uso durante seis semanas posteriores a la vacunación, por riesgo de síndrome de Reye', 'Se deben administrar salicilatos de forma profiláctica tras la vacunación', 'Solo se debe evitar el uso durante 24 horas', 'B', 'El manual señala que se recomienda evitar el uso de salicilatos durante las seis semanas posteriores a la vacunación contra la varicela en menores de 18 años, debido al riesgo de síndrome de Reye. Referencia: Capítulo 9. Enfermedades y vacunas. 9.13.1 Vacuna contra la varicela. Tabla 54 y 55. Página 172 y 174.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('b7ccf786-ac3e-57cb-bd4d-65a0ce901ace', 'Según el manual, ¿qué genotipos de VPH son responsables del 70% de los casos de cáncer de cuello uterino?', '6 y 11', '31 y 33', '16 y 18', '45 y 52', 'C', 'El manual indica que se han identificado 16 tipos de VPH de alto riesgo, siendo los genotipos 16 y 18 los responsables del 70% de los casos de cáncer de cuello uterino y de tumores como anales, vulvares y peneanos. Referencia: Capítulo 9. Enfermedades y vacunas. 9.14 Infección por el virus del papiloma humano. Página 174.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('92f5f4f7-09f3-581c-acfd-d884443d143d', 'Según el manual, ¿a qué edad y con qué esquema se administra la vacuna nonavalente contra el VPH en el esquema nacional?', 'A los 15 años, dos dosis', 'Al nacer, dosis única', 'A los 5 años, tres dosis', 'A los 9 años, dosis única', 'D', 'El manual indica que la vacuna nonavalente contra el VPH se administra en niños y niñas de 9 años de edad, en esquema temprano de dosis única. Referencia: Capítulo 9. Enfermedades y vacunas. 9.14.2 Vacuna nonavalente contra el VPH. Tabla 59. Página 178.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('a764e4a4-7d13-5b97-b90e-2c57592ecf70', 'Caso clínico: Un lactante de 6 meses va a viajar con su familia a una zona con riesgo de transmisión de fiebre amarilla. Según el manual, ¿cuál es la recomendación respecto a la vacuna contra la fiebre amarilla en este lactante?', 'La vacuna está contraindicada en menores de seis meses, y no se recomienda entre los seis y ocho meses, excepto en situaciones epidémicas', 'Debe recibir la vacuna de inmediato sin ninguna restricción', 'Debe recibir dos dosis simultáneas para mayor protección', 'No existe ninguna vacuna contra fiebre amarilla en el esquema', 'A', 'El manual establece que la vacuna contra la fiebre amarilla está contraindicada en lactantes menores de seis meses de edad y no se recomienda su administración entre los seis y ocho meses, excepto durante situaciones epidémicas. Referencia: Capítulo 9. Enfermedades y vacunas. 9.15.1 Vacuna contra la fiebre amarilla. Tabla 63. Página 182.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('aef4a521-68b8-519e-abac-3fb6b7d49eb7', 'Según el manual, ¿cuáles son las dos reacciones adversas raras y graves específicamente asociadas a la vacuna contra la fiebre amarilla?', 'Meningitis aséptica y trombocitopenia', 'Enfermedad neurotrópica (YEL-AND) y enfermedad viscerotrópica (YEL-AVD)', 'Poliomielitis asociada a la vacuna', 'Reacción de Arthus y encefalopatía por pertussis', 'B', 'El manual describe entre las reacciones raras de la vacuna FA la enfermedad neurotrópica (YEL-AND) y la enfermedad viscerotrópica (YEL-AVD), con tasas de 0,8 y 0,3 por 100.000 dosis respectivamente. Referencia: Capítulo 9. Enfermedades y vacunas. 9.15.1 Vacuna contra la fiebre amarilla. Tabla 63. Página 182.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('a0b2fc41-095d-5e5e-a021-2f61845af422', 'Caso clínico: Una persona sufre una mordedura profunda de un perro callejero con sangrado, en una zona endémica de rabia. Según la clasificación de la OMS citada en el manual, ¿a qué categoría de exposición corresponde este caso y qué recomendación aplica?', 'Categoría I; no requiere profilaxis posexposición', 'Categoría II; solo requiere limpieza y esquema vacunal', 'Categoría III; requiere limpieza, vacunación e inmunoglobulina', 'No corresponde a ninguna categoría descrita', 'C', 'El manual, citando las recomendaciones de la OMS, clasifica como Categoría III las mordeduras profundas o el contacto con mucosas o piel lesionada, recomendando limpieza, vacunación e inmunoglobulina; el caso descrito (mordedura profunda con sangrado) corresponde a esta categoría. Referencia: Capítulo 9. Enfermedades y vacunas. 9.16.1 Vacuna contra la rabia humana. Tabla 67. Página 187.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('8752e987-30e1-5ea1-b9be-c0d5ea2d2b9a', 'Según el manual, ¿hasta qué día posterior al inicio del esquema vacunal antirrábico se puede administrar la inmunoglobulina específica?', 'Hasta el día 3', 'Hasta el día 14', 'No existe límite de tiempo', 'Hasta el día 7', 'D', 'El manual indica que no se debe aplicar inmunoglobulina pasados los 7 días desde el inicio del esquema vacunal, ya que los anticuerpos pasivos pueden interferir con la respuesta a la vacuna antirrábica administrada previamente. Referencia: Capítulo 9. Enfermedades y vacunas. 9.16.2 Inmunoglobulina humana antirrábica. Página 188-189.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('c9d83e44-8a95-52e2-9e64-cd1a43ad9bbc', 'Según el manual, ¿cuál es la vía de administración recomendada para la vacuna antirrábica y qué zona anatómica debe evitarse?', 'Intramuscular, ángulo 90°; no administrar en glúteo', 'Subcutánea, ángulo 45°; puede administrarse en cualquier sitio', 'Intradérmica, ángulo 15°; solo en el abdomen', 'Vía oral, sin restricciones anatómicas', 'A', 'El manual indica que la vacuna antirrábica se administra por vía intramuscular, con ángulo de 90°, en la cara anterolateral del muslo (niños pequeños) o región deltoidea (niños mayores y adultos), señalando expresamente que no se debe administrar en glúteo. Referencia: Capítulo 9. Enfermedades y vacunas. 9.16.1 Vacuna contra la rabia humana. Tabla 65 y 66. Página 185 y 187.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('056ef6a5-497c-5353-bfa2-b7cf9debd6cf', 'Según el manual, ¿cuál es la eficacia aproximada de la vacuna trivalente inactivada contra la influenza frente a la enfermedad virológicamente confirmada en población infantil mayor de dos años?', 'Aproximadamente 10%', 'Aproximadamente 70%', 'Aproximadamente 100% en todos los casos', 'No se ha determinado su eficacia', 'B', 'El manual indica que en la población infantil mayor de dos años, la eficacia frente a la enfermedad virológicamente confirmada con vacuna trivalente inactivada puede alcanzar aproximadamente un 70%. Referencia: Capítulo 9. Enfermedades y vacunas. 9.17.1 Vacuna contra la influenza trivalente. Página 192.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('88ad7a35-7cd1-5634-a13c-b3fee3be66f1', 'Según el manual, ¿cuál es la principal contraindicación etaria para la vacuna contra la influenza?', 'Niños mayores de 5 años', 'Adultos mayores de 65 años', 'Lactantes menores de 6 meses', 'No existe contraindicación por edad', 'C', 'El manual indica que las contraindicaciones de la vacuna contra la influenza incluyen a lactantes menores de 6 meses, enfermedad febril aguda grave e hipersensibilidad a los componentes de la vacuna. Referencia: Capítulo 9. Enfermedades y vacunas. Tabla 70. Consideraciones de seguridad de la vacuna contra la influenza. Página 193.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('5f02f681-d836-5da5-b623-5ccac16039b6', 'Caso clínico: Una gestante entre las 32 y 36 semanas de gestación acude a control prenatal. Según el manual, ¿qué vacuna del esquema nacional está indicada específicamente en este rango gestacional para proteger al recién nacido frente a infecciones respiratorias?', 'Vacuna BCG', 'Vacuna SRP', 'Vacuna contra la fiebre amarilla', 'Vacuna contra el virus sincitial respiratorio (VSR)', 'D', 'El manual indica que la vacuna contra el virus sincitial respiratorio (VSR) está indicada en embarazadas de 32 a 36 semanas de gestación, con el objetivo de proteger al recién nacido durante sus primeros meses de vida, reduciendo el riesgo de enfermedad respiratoria significativa. Referencia: Capítulo 9. Enfermedades y vacunas. 9.20.1 Vacuna contra el virus sincitial respiratorio. Tabla 80. Página 205.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('ec5e43b4-d4ae-50e3-bd0f-7b18949ce87c', 'Según el manual, ¿qué enfermedades cubre la vacuna pentavalente (DPwT+HB+Hib)?', 'Difteria, tosferina, tétanos, hepatitis B e infecciones invasivas por Haemophilus influenzae tipo B', 'Sarampión, rubéola, parotiditis, varicela y hepatitis A', 'Neumococo, rotavirus, VPH, influenza y COVID-19', 'Únicamente difteria y tétanos', 'A', 'El manual describe a la vacuna pentavalente (DPwT+HB+Hib) como una combinación que protege contra cinco enfermedades: difteria, tosferina, tétanos, hepatitis B e infecciones invasivas por Haemophilus influenzae tipo B. Referencia: Capítulo 10. Inmunización complementaria al esquema nacional. 10.1 Vacuna pentavalente. Página 207.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('217e069e-a717-504e-a843-e29eb151d4fb', 'Según el manual, ¿las vacunas descritas en el Capítulo 10 de inmunización complementaria forman parte del esquema nacional obligatorio?', 'Sí, todas son de aplicación obligatoria en el sector público', 'No forman parte del Esquema Nacional de Vacunación; se encuentran disponibles y se aplican en el sector privado, pudiendo valorarse su inclusión futura', 'Solo se aplican en campañas de emergencia declaradas', 'Están reservadas exclusivamente para personal militar', 'B', 'El manual aclara que las vacunas descritas en el Capítulo 10 no forman parte del Esquema Nacional de Vacunación, aunque se encuentran disponibles y se aplican en el sector privado; el MSP podrá valorar de forma progresiva su eventual inclusión en el esquema nacional según evidencia científica y disponibilidad presupuestaria. Referencia: Capítulo 10. Inmunización complementaria al esquema nacional. Página 207.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('254cecaa-f414-5343-8210-ba61581f2765', 'Según el manual, en contexto de un brote, ¿hasta qué edad límite puede utilizarse la vacuna pentavalente como primer y segundo refuerzo?', 'Hasta los 2 años exclusivamente', 'Hasta los 18 meses exclusivamente', 'Hasta los 6 años 11 meses 29 días', 'No tiene límite de edad', 'C', 'El manual indica que en contexto de un brote, la vacuna pentavalente podrá ser utilizada como primer y segundo refuerzo con límite de edad hasta los 6 años 11 meses 29 días. Referencia: Capítulo 10. Inmunización complementaria al esquema nacional. 10.1 Vacuna pentavalente. Página 207.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('c81e4015-4be1-536a-b0c5-b1796ceef061', 'Según el manual, ¿cómo se define una oportunidad perdida de vacunación (OPDV)?', 'Cuando una persona rechaza voluntariamente la vacunación por razones personales', 'Cuando una vacuna caduca en el almacén sin ser utilizada', 'Cuando el paciente no puede pagar el costo de la vacuna', 'Toda situación por la que cualquier individuo elegible para la vacunación no recibe las vacunas necesarias, aunque no tenga ninguna contraindicación, al acudir al establecimiento de salud', 'D', 'El manual define la OPDV como toda situación por la que cualquier individuo que es elegible para la vacunación no recibe las vacunas necesarias aunque no tenga ninguna contraindicación, cuando acude al establecimiento de salud. Referencia: Capítulo 11. Oportunidades perdidas de vacunación. Página 218.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('d6ec76de-e42f-5ef6-a52a-c8b59c3041ac', 'Caso clínico: Un lactante de 3 meses acude a consulta por un resfriado común, con temperatura de 37,5°C, y su esquema de vacunación está al día para ser aplicado en esta cita. Según la Tabla 82 del manual, ¿corresponde diferir la vacunación en este caso?', 'No; la enfermedad aguda leve con fiebre ≤38°C, como el resfriado común, es una falsa contraindicación y no impide la vacunación', 'Sí, cualquier enfermedad debe diferir la vacunación', 'Sí, se debe esperar a la resolución completa del resfriado antes de vacunar', 'No se puede determinar sin exámenes de laboratorio', 'A', 'El manual señala explícitamente que la presencia de enfermedades agudas y leves con o sin fiebre ≤38°C (como resfriado común, rinitis, diarrea leve) constituye una falsa contraindicación, siendo la causa técnica principal de OPDV, por lo que no impide la vacunación. Referencia: Capítulo 11. Oportunidades perdidas de vacunación. 11.2 Criterios de elegibilidad clínica. Tabla 82. Página 220.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('d55a6c08-94f4-5951-9a84-dad41862ae3a', 'Caso clínico: Un niño presentó una reacción anafiláctica tras la administración previa de una dosis de determinada vacuna. Según la Tabla 82 del manual, ¿cuál es la recomendación para futuras dosis de esa misma vacuna?', 'Diferir la vacunación hasta que mejore el cuadro clínico', 'No vacunar; se trata de una contraindicación absoluta', 'Vacunar con precaución, sin ninguna restricción especial', 'Administrar una dosis reducida', 'B', 'El manual clasifica la anafilaxia previa a una dosis de la vacuna a administrar como una contraindicación absoluta, cuya recomendación es no vacunar con esa vacuna específica. Referencia: Capítulo 11. Oportunidades perdidas de vacunación. Tabla 82. Página 220.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('143db238-3659-51a5-9b0f-d13ebed3378a', 'Según el manual, ¿cuál de las siguientes situaciones constituye una FALSA contraindicación para la vacunación?', 'Anafilaxia previa a una dosis de la vacuna a administrar', 'Enfermedad aguda moderada o grave con fiebre igual o mayor a 38°C', 'Recién nacido prematuro', 'Crisis asmática descompensada', 'C', 'El manual lista explícitamente entre las falsas contraindicaciones el ser recién nacido prematuro, junto con enfermedades agudas leves, tratamiento antibiótico, bajas dosis de corticoides, lactancia materna, contacto con embarazadas, antecedentes familiares de alergia o convulsiones, desnutrición, entre otras. Referencia: Capítulo 11. Oportunidades perdidas de vacunación. 11.2 Criterios de elegibilidad clínica. Página 220.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('4bac4dc4-cf29-5ee6-85c0-03b8aa14c3d1', 'Caso clínico: Un recién nacido prematuro de 30 semanas de gestación, clínicamente estable, se encuentra hospitalizado. Según la Tabla 84 del manual, ¿desde qué edad gestacional se recomienda aplicar la vacuna BCG en prematuros?', 'Desde las 24 semanas', 'Solo después del alta hospitalaria, sin importar la edad gestacional', 'Nunca en prematuros', 'Desde las 31 semanas de edad gestacional', 'D', 'La Tabla 84 del manual indica que la BCG debe aplicarse desde las 31 semanas de edad gestacional en recién nacidos prematuros, señalando que en aquellos con menos de 1.500 g se debe vigilar por 48 horas por posible apnea o bradicardia. Referencia: Capítulo 12. Vacunación en situaciones especiales. 12.1 Vacunación en recién nacidos prematuros. Tabla 84. Página 224.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('1f73699a-29b0-58b4-bbb1-89e448954a28', 'Según el manual, ¿el peso al nacer o la edad gestacional constituyen, por sí solos, una contraindicación para iniciar el calendario de inmunización en recién nacidos prematuros?', 'No; los recién nacidos prematuros deben vacunarse según su edad cronológica, siempre que se encuentren clínicamente estables, y el peso o la edad gestacional no constituyen contraindicaciones', 'Sí, siempre son contraindicación absoluta', 'Solo el peso es contraindicación, la edad gestacional no', 'Solo la edad gestacional es contraindicación, el peso no', 'A', 'El manual establece explícitamente que los recién nacidos prematuros deben vacunarse según su edad cronológica, siempre que se encuentren clínicamente estables, y que el peso al nacer o la edad gestacional no constituyen contraindicaciones. Referencia: Capítulo 12. Vacunación en situaciones especiales. 12.1 Vacunación en recién nacidos prematuros. Página 223.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('94a7ef64-2747-5f27-8aed-3bcea84843c4', 'Caso clínico: Un recién nacido prematuro de 30 semanas de gestación, con peso al nacer de 1.400 g, será vacunado. Según el manual, ¿qué vigilancia especial se recomienda tras la vacunación en este paciente?', 'Ninguna vigilancia adicional es necesaria', 'Vigilancia cardiorrespiratoria estrecha durante las 48 a 72 horas posteriores a la vacunación', 'Vigilancia únicamente durante los primeros 5 minutos', 'Aislamiento respiratorio por 30 días', 'B', 'El manual recomienda que en los lactantes prematuros con ≤31 semanas de gestación, peso al nacer <2.000 g, antecedentes de apnea o bradicardia, o diagnóstico de displasia broncopulmonar grave, se realice una vigilancia cardiorrespiratoria estrecha durante las 48 a 72 horas posteriores a la vacunación. Referencia: Capítulo 12. Vacunación en situaciones especiales. 12.2 Vacunación en recién nacidos prematuros hospitalizados. Página 224.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('c96a2440-4930-5ae1-97ee-aabce1e5b127', 'Caso clínico: Una mujer embarazada que amamanta desea saber si puede recibir la vacuna contra la fiebre amarilla antes de un viaje. Según el manual, ¿qué recomendación se aplica respecto a la lactancia y esta vacuna en particular?', 'Ninguna vacuna está contraindicada durante la lactancia, incluida la fiebre amarilla, sin ninguna precaución adicional', 'La lactancia siempre contraindica cualquier vacunación materna', 'Ninguna vacuna está contraindicada por la lactancia, a excepción de la fiebre amarilla; si es necesaria en madres que amamantan a menores de 9 meses, se debe suspender la lactancia y desechar la leche extraída durante 2 semanas', 'No existe ninguna consideración especial sobre este tema en el manual', 'C', 'El manual señala que ninguna vacuna está contraindicada para una mujer por el hecho de estar lactando a su hijo, a excepción de la vacuna de la fiebre amarilla; si es precisa su administración en madres que amamanten a menores de 9 meses, deberán suspenderla y desechar la leche extraída durante 2 semanas tras la vacunación. Referencia: Capítulo 12. Vacunación en situaciones especiales. 12.9.1 Vacunación en embarazadas. Tabla 89. Página 240.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('36688a62-6462-55c9-a71c-0dc1f1d1b601', 'Según el manual, ¿en qué momento se recomienda que las vacunas de antígenos atenuados se administren en relación con la concepción, en mujeres que planean un embarazo?', 'Pueden administrarse en cualquier momento del embarazo sin restricción', 'Únicamente después del parto', 'No existe ninguna recomendación al respecto', 'Al menos un mes antes de la concepción', 'D', 'El manual indica que las vacunas inactivadas pueden aplicarse antes o durante el embarazo, mientras que las atenuadas deben administrarse al menos un mes antes de la concepción. Referencia: Capítulo 12. Vacunación en situaciones especiales. 12.9.1 Vacunación en embarazadas. Página 239.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('39409eb4-a40a-5a4c-99ab-c450ecb3b0a9', 'Según el manual, ¿cómo se clasifica un ESAVI que pone en riesgo la vida del vacunado, puede requerir hospitalización o provocar discapacidad persistente?', 'ESAVI grave', 'ESAVI no grave', 'Falsa contraindicación', 'Reacción esperada sin necesidad de notificación', 'A', 'El manual clasifica como ESAVI graves aquellos que ponen en peligro la vida ya que pueden provocar la muerte, requerir hospitalización o prolongar la estancia hospitalaria, provocar una discapacidad persistente o significativa, o asociarse a mayor riesgo de aborto o anomalía congénita. Referencia: Capítulo 14. Eventos supuestamente atribuibles a la vacunación o inmunización (ESAVI). Página 245-246.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('2f2e64dc-0d88-59b9-9591-11121f2fb0fb', 'Según la Tabla 90 del manual, ¿cuál es el período de riesgo y la tasa de incidencia aproximada de la meningitis aséptica asociada a la vacuna SRP?', 'En la primera hora; 1-2 por 1.000.000 vacunados', '2-3 semanas; 1-10 por 100.000 vacunados', '1-2 días; 50% de los vacunados', '8-9 días; 1 por 30.000 vacunados', 'B', 'La Tabla 90 del manual indica que la meningitis aséptica asociada a la vacuna SRP tiene un período de riesgo de 2-3 semanas, con una tasa de incidencia de 1-10 por 100.000 vacunados, clasificada como ESAVI grave. Referencia: Capítulo 14. Eventos supuestamente atribuibles a la vacunación o inmunización (ESAVI). Tabla 90. Página 246.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('9314b904-edaa-5f74-bd7f-d6be511da714', 'Según el manual, ¿a qué entidad corresponde en Ecuador la notificación, investigación, registro y clasificación general de los ESAVI?', 'Únicamente al establecimiento de salud donde ocurrió el evento, sin articulación con otras instancias', 'Exclusivamente al fabricante de la vacuna', 'A la Agencia Nacional de Regulación, Control y Vigilancia Sanitaria (ARCSA)', 'A la Organización Mundial de la Salud directamente', 'C', 'El manual establece que en Ecuador la notificación, investigación, registro y clasificación de los ESAVI recae en la Agencia Nacional de Regulación, Control y Vigilancia Sanitaria (ARCSA), o la entidad que cumpla sus funciones; en casos de eventos graves interviene también la Dirección Nacional de Vigilancia Epidemiológica (DNVE). Referencia: Capítulo 14. Eventos supuestamente atribuibles a la vacunación o inmunización (ESAVI). Página 245.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('77791842-3e9f-512f-a09b-dd5d89841f84', 'Según la Tabla 90 del manual, ¿cuál es la tasa de incidencia aproximada de fiebre tras la administración de la vacuna DPT, en el período de 1-2 días?', '1-6%', '10,5%', '12%', '50%', 'D', 'La Tabla 90 del manual indica que la fiebre en el período de 1-2 días posteriores a la vacuna DPT presenta una tasa de incidencia del 50%, clasificada como ESAVI no grave. Referencia: Capítulo 14. Eventos supuestamente atribuibles a la vacunación o inmunización (ESAVI). Tabla 90. Página 246.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('1de93ad0-567a-58f6-ba6e-9fea2363028c', 'Caso clínico: Un niño de 4 años requiere aplicación de la vacuna SRP y, en el mismo brazo, la vacuna contra la varicela, en la misma sesión. Según el manual, ¿cuál es la vía y el ángulo de administración correctos para ambas vacunas?', 'Vía subcutánea, ángulo 45°', 'Vía intramuscular, ángulo 90°', 'Vía intradérmica, ángulo 15°', 'Vía oral, sin aguja', 'A', 'El manual indica que tanto la vacuna SRP como la vacuna contra la varicela se administran por vía subcutánea, con un ángulo de 45°, generalmente en la región deltoidea. Referencia: Capítulo 9. Enfermedades y vacunas. Tabla 46 y Tabla 54. Páginas 161 y 172.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('a15821bd-10bf-558e-9a26-f6094f600afb', 'Según el manual, ¿cuál es la efectividad aproximada de al menos una dosis de la vacuna neumococo 13-valente (PCV13) contra la enfermedad neumocócica invasiva (ENI) por serotipos vacunales, en niños europeos?', 'Aproximadamente 30%', 'Aproximadamente 84%', 'Aproximadamente 50%', 'Aproximadamente 99%', 'B', 'El manual indica que la efectividad de al menos una dosis de PCV13 contra ENI por serotipos vacunales es de aproximadamente 84% en niños europeos, con eficacia particularmente alta para serotipos como 1, 19A y 6C, aunque menor para el serotipo 3. Referencia: Capítulo 9. Enfermedades y vacunas. 9.12.1 Vacuna conjugada contra el neumococo 13-valente. Página 166.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('a2d8eab0-e904-59b7-89b8-edba4af0de67', 'Según el manual, ¿qué proporción aproximada de niños desarrolla niveles protectores frente a todas las enfermedades incluidas en la vacuna hexavalente, tras completar la serie primaria de tres dosis?', 'Al menos 50%', 'Al menos 20%', 'Al menos 95,7%', '100% sin excepción', 'C', 'El manual indica que después de completar la serie primaria de 3 dosis, al menos el 95,7% de los niños desarrollan niveles protectores frente a todas las enfermedades incluidas en la vacuna hexavalente combinada. Referencia: Capítulo 9. Enfermedades y vacunas. 9.7.1 Vacuna hexavalente celular. Página 151.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('6fb43173-47e7-5079-b4b8-49d53913ae09', 'Según el manual, ¿qué elementos conforman la cadena de frío en términos de recursos o equipamientos materiales?', 'Únicamente el personal sanitario capacitado', 'Únicamente los vehículos de transporte terrestre', 'Solo los sistemas informáticos de registro', 'La cadena fija (refrigeradores y congeladores para almacenamiento estático) y la cadena móvil (cajas frías, termos, neveras portátiles y otros medios de transporte)', 'D', 'El manual indica que los recursos o equipamientos materiales de la cadena de frío comprenden la cadena fija (refrigeradores y congeladores para almacenamiento estático) y la cadena móvil (cajas frías, termos, neveras portátiles y otros medios de transporte), además de los recursos humanos capacitados. Referencia: Capítulo 3. Cadena de frío. 3.2 Elementos de la cadena de frío. Página 40.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'Manual de Inmunizaciones MSP 2026'),
  ('da804b55-b24e-55a6-a68f-15e05506379d', 'Según el manual del MAIS-FCI, ¿qué porcentaje de los problemas de salud de la población pueden resolverse en el primer y segundo nivel de atención?', 'Más del 90%', 'El 100%, sin necesidad de otros niveles', 'Menos del 30%', 'Alrededor del 50%', 'A', 'Referencia: Capítulo 1. Ecuador: el Sistema Nacional de Salud: antecedentes, avances y retos. Página 23.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('2db8e730-4220-557f-9749-9293fb0803c1', 'Según el manual, ¿cuáles son, en orden de frecuencia, las dos primeras causas de muerte reportadas en el Ecuador según los datos citados (MSP, INEC 2010)?', 'Accidentes de transporte e influenza y neumonía', 'Diabetes mellitus y enfermedades cerebrovasculares', 'Cáncer de estómago e insuficiencia cardíaca', 'Violencia y cirrosis', 'B', 'Referencia: Capítulo 1. Ecuador: el Sistema Nacional de Salud: antecedentes, avances y retos. Página 24.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('a2e74daf-7b9a-5686-9c8e-4a76df3a6beb', 'Según el manual, ¿cuál fue una de las características históricas que definieron al Sistema Nacional de Salud del Ecuador antes del proceso de transformación descrito?', 'Un enfoque exclusivamente preventivo y comunitario', 'La ausencia total de establecimientos de tercer nivel', 'Estar fragmentado, centralizado y desarticulado en la provisión de servicios de salud', 'Un sistema totalmente descentralizado y articulado desde su origen', 'C', 'Referencia: Capítulo 1. Ecuador: el Sistema Nacional de Salud: antecedentes, avances y retos. Página 23.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('2f8d956e-f5b1-5021-bbed-02ca91fc767c', 'Según el manual, ¿qué estrategia se implementó para fortalecer el primer nivel de atención junto con el Modelo de Atención Integral de Salud, según lo descrito en el Capítulo 1?', 'La reducción del presupuesto en salud', 'La eliminación de la gratuidad de los servicios de salud', 'La creación exclusiva de hospitales de cuarto nivel', 'La constitución de los Equipos Básicos de Salud (EBAS)', 'D', 'Referencia: Capítulo 1. Ecuador: el Sistema Nacional de Salud: antecedentes, avances y retos. Página 25.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('f08c1a6f-5efc-598c-a14d-156b93c741cf', 'Según el manual, ¿con qué otros derechos se vincula el ejercicio del derecho a la salud, de acuerdo con el Artículo 32 de la Constitución de la República?', 'Con el derecho al agua, la alimentación, la educación, la cultura física, el trabajo, la seguridad social y otros que sustentan el buen vivir', 'Exclusivamente con el derecho al trabajo', 'El artículo no vincula el derecho a la salud con ningún otro derecho', 'Únicamente con el derecho a la seguridad social', 'A', 'Referencia: Capítulo 2. Marco legal y normativo relacionado al sector salud. Sección 2.1. Constitución de la República del Ecuador. Art. 32. Página 29.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('f92f3e01-a4fc-516f-83b1-f218158702b4', 'Caso clínico: Un equipo de salud del primer nivel de atención debe identificar a los grupos que, según la Constitución, requieren atención prioritaria y especializada. Según el manual, ¿en qué artículo constitucional se establecen los grupos de atención prioritaria y cuáles son algunos de los grupos mencionados?', 'Art. 66; personas con discapacidad auditiva únicamente', 'Art. 35; adultos mayores, mujeres embarazadas, niños, niñas y adolescentes, personas con discapacidad, entre otros', 'Art. 361; personal de salud del sector público', 'Art. 18; personas que accedan a información pública', 'B', 'Referencia: Capítulo 2. Marco legal y normativo relacionado al sector salud. Sección 2.1. Constitución de la República del Ecuador. Art. 35. Página 29.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('a913c767-6652-58d2-bd9f-28433e50a410', 'Según el manual, ¿qué establece el Artículo 361 de la Constitución respecto a la rectoría del Sistema Nacional de Salud?', 'Que no existe una autoridad rectora única en el sistema de salud', 'Que la rectoría corresponde a los gobiernos autónomos descentralizados', 'Que el Estado ejercerá la rectoría del sistema a través de la autoridad sanitaria nacional, responsable de formular, normar, regular y controlar la política de salud', 'Que la rectoría se delega completamente a la Red Complementaria privada', 'C', 'Referencia: Capítulo 2. Marco legal y normativo relacionado al sector salud. Sección 2.1. Constitución de la República del Ecuador. Art. 361. Página 30.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('4c2343b6-9b7c-556a-ab3f-c3d66d318ff9', 'Según el manual, ¿qué establece el Artículo 361 de la Constitución respecto a la naturaleza de los servicios públicos de salud?', 'Que se financiarán únicamente con seguros individuales', 'Que serán exclusivamente privados', 'Que solo cubrirán a la población urbana', 'Que serán universales y gratuitos', 'D', 'Referencia: Capítulo 2. Marco legal y normativo relacionado al sector salud. Sección 2.1. Constitución de la República del Ecuador. Art. 361. Página 30.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('676cddb0-3b16-5c2e-a88c-1495b704a8d5', 'Según el manual, ¿qué establece el Código Orgánico de Planificación y Finanzas Públicas (Art. 31) respecto al acceso a la información para la construcción de políticas públicas?', 'Que será de libre acceso, tanto para personas naturales como jurídicas públicas y privadas, salvo casos señalados por la ley', 'Que será de acceso exclusivo para entidades gubernamentales', 'Que se mantendrá en reserva absoluta por motivos de seguridad nacional', 'Que solo podrá solicitarse mediante orden judicial', 'A', 'Referencia: Capítulo 2. Marco legal y normativo relacionado al sector salud. Código Orgánico de Planificación y Finanzas Públicas. Art. 31. Página 30.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('7d289856-d0e8-5734-a110-0dfccd3601a7', 'Según el manual, ¿en qué artículos de la Constitución se establece la creación, los principios, componentes, características y garantías del Sistema Nacional de Salud (SNS)?', 'Artículos 1 al 10', 'Artículos 358, 359, 360 y 361', 'Artículos 18, 30, 31 y 32', 'Artículos 66 y 95 únicamente', 'B', 'Referencia: Capítulo 2. Marco legal y normativo relacionado al sector salud. Sección 2.1. Constitución de la República del Ecuador. Página 30.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('27d9813b-9fde-5904-b882-403c19068343', 'Según el manual, ¿qué reconoce la Constitución respecto a la participación de la comunidad, de acuerdo a los artículos 95 y 208?', 'Que la participación ciudadana está prohibida en asuntos de salud', 'Que la participación se limita a procesos electorales', 'Que la participación ciudadana se constituye en el Quinto Poder del Estado', 'Que solo el personal de salud puede participar en la toma de decisiones', 'C', 'Referencia: Capítulo 2. Marco legal y normativo relacionado al sector salud. Sección 2.1. Constitución de la República del Ecuador. Art. 95, 208. Página 30.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('a5e103da-a2fa-5ad3-9417-f79af5834e6b', 'Según el manual, ¿cómo define la Organización Mundial de la Salud (OMS, 1946) el concepto de salud?', 'Un estado exclusivamente biológico determinado por la genética', 'La capacidad de trabajar sin síntomas físicos', 'La ausencia de enfermedades diagnosticadas por un médico', 'Un estado de completo bienestar físico, mental y social, y no solamente la ausencia de afecciones o enfermedades', 'D', 'Referencia: Capítulo 3. Marco conceptual del Modelo de Atención Integral de Salud. Sección 3.1. Salud. Página 39.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('f96387e7-e5bf-54e7-aed5-c450021883bc', 'Según el modelo de determinantes de la salud citado por el manual (Marc Lalonde, 1974), ¿cuáles son las cuatro categorías de determinantes descritas?', 'Conductuales, ambientales, biológicos y sociales', 'Nutricionales, educativos, laborales y religiosos', 'Hospitalarios, comunitarios, familiares e individuales', 'Genéticos, ambientales, económicos y políticos', 'A', 'Referencia: Capítulo 3. Marco conceptual del Modelo de Atención Integral de Salud. Sección 3.2. Determinantes de la Salud. Ilustración 2. Página 42.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('2237236e-dea9-5399-90c9-be8451e3debe', 'Según el manual, citando el informe Landone (1974), ¿qué porcentaje de la mortalidad en los países puede atribuirse a riesgos ambientales?', '80%', '20%', '50%', '5%', 'B', 'Referencia: Capítulo 3. Marco conceptual del Modelo de Atención Integral de Salud. Sección 3.2. Determinantes de la Salud. Determinantes ambientales. Página 41.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('4983e25f-70f8-50ac-a4a1-dc0096734236', 'Según el manual, ¿en qué año y lugar se formuló la Declaración que dio origen a la estrategia de Atención Primaria de Salud (APS)?', '1992, en Santa Fe de Bogotá', '1986, en Ottawa', '1978, en Alma Ata', '2008, en Quito', 'C', 'Referencia: Capítulo 3. Marco conceptual del Modelo de Atención Integral de Salud. Sección 3.3.1. La Atención Primaria de Salud Renovada (APS-R). Página 42.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('91f0e58d-74f4-578c-909d-3f9013647f02', 'Según el manual, ¿qué definición de promoción de la salud se estableció en la Primera Conferencia Internacional de Promoción de la Salud (Ottawa, 1986)?', 'La construcción de hospitales de tercer nivel en zonas rurales', 'La eliminación de todas las enfermedades infecciosas', 'La provisión exclusiva de medicamentos gratuitos a la población', 'El proceso de capacitar a las personas para que aumenten el control sobre su salud y para que la mejoren', 'D', 'Referencia: Capítulo 3. Marco conceptual del Modelo de Atención Integral de Salud. Sección 3.3.1. La Atención Primaria de Salud Renovada (APS-R). Página 42.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('8667a1bf-8714-5b51-bfd4-2950f23e3af5', 'Según el manual, ¿qué efecto tuvo el pensamiento y la práctica neoliberal de la década de los noventa sobre la estrategia de APS?', 'La redujo a intervenciones puntuales, focalizadas, locales y de bajo costo, coartando su potencial transformador', 'No tuvo ningún efecto sobre la implementación de la APS', 'Eliminó por completo la estrategia de APS en el mundo', 'Fortaleció y amplió su alcance en todos los países de la región', 'A', 'Referencia: Capítulo 3. Marco conceptual del Modelo de Atención Integral de Salud. Sección 3.3.1. La Atención Primaria de Salud Renovada (APS-R). Página 42.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('ea6013c5-e577-5f96-882b-e2f6a36a8726', 'Caso clínico: El equipo de salud del primer nivel de atención debe orientar su accionar considerando el enfoque integral que promueve el MAIS-FCI, más allá de la dimensión biológica de la enfermedad. Según el manual, ¿hacia qué dimensiones se orienta el MAIS-FCI en la construcción, cuidado y recuperación de la salud?', 'Únicamente hacia la dimensión biológica', 'Hacia todas sus dimensiones: biológicas, mentales, espirituales, psicológicas y sociales', 'Solo hacia la dimensión hospitalaria', 'Exclusivamente hacia la dimensión económica', 'B', 'Referencia: Capítulo 3. Marco conceptual del Modelo de Atención Integral de Salud. Sección 3.1. Salud. Página 40.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('d61450ce-0ab9-589d-848f-7c4c09aa79f6', 'Según el manual, ¿qué ejes de desigualdad incluye el determinante denominado ''posición socioeconómica''?', 'Únicamente la edad biológica', 'Exclusivamente el nivel educativo formal', 'La clase social, la posición socioeconómica, el género y la pertenencia étnica', 'Solamente el lugar de nacimiento', 'C', 'Referencia: Capítulo 3. Marco conceptual del Modelo de Atención Integral de Salud. Sección 3.2. Determinantes de la Salud. Posición socioeconómica. Página 40.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('2fad0eb4-3774-54a6-9801-38be3236a1ed', 'Según el manual, ¿cuál de los siguientes se describe como un factor intermediario que determina desigualdades en salud?', 'El color de ojos de la persona', 'El signo zodiacal', 'El número de hermanos que tiene la persona', 'Las circunstancias materiales, como la vivienda, el nivel de ingresos o las condiciones de trabajo', 'D', 'Referencia: Capítulo 3. Marco conceptual del Modelo de Atención Integral de Salud. Sección 3.2. Determinantes de la Salud. Determinantes intermedios. Página 41.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('58d0ab7d-da17-57b4-8cb5-045dda1d0254', 'Según el manual, ¿cuál es el propósito del Modelo de Atención Integral de Salud Familiar, Comunitario e Intercultural (MAIS-FCI)?', 'Orientar el accionar integrado de los actores del Sistema Nacional de Salud hacia la garantía de los derechos en salud y el cumplimiento de las metas del Plan Nacional de Desarrollo', 'Aumentar exclusivamente el número de camas hospitalarias', 'Privatizar progresivamente los servicios de salud', 'Centrar la atención exclusivamente en la enfermedad y el enfoque biologista', 'A', 'Referencia: Capítulo 4. El Modelo de Atención Integral de Salud Familiar Comunitario e Intercultural. Sección 4.2. Propósito del MAIS-FCI. Página 56.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('cd790b20-bdc7-502b-8d68-8b7a47370f0d', 'Según el manual, ¿cuál es el objetivo del Modelo de Atención Integral de Salud Familiar, Comunitario e Intercultural?', 'Concentrar todas las prestaciones únicamente en el tercer nivel de atención', 'Integrar y consolidar la Atención Primaria de Salud Renovada (APS-R) en los tres niveles de atención, reorientando los servicios hacia la promoción y prevención', 'Reducir el número de establecimientos de primer nivel', 'Eliminar la participación comunitaria en la toma de decisiones', 'B', 'Referencia: Capítulo 4. El Modelo de Atención Integral de Salud Familiar Comunitario e Intercultural. Sección 4.3. Objetivo del MAIS-FCI. Página 56.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('2b48d06b-4ebf-53c0-a6b2-f65921a789ae', 'Según el manual, el objetivo estratégico 4.4.2 del MAIS busca acercar los servicios de salud a la comunidad. ¿Qué establece este objetivo respecto al primer nivel de atención?', 'Que solo atienda emergencias', 'Que se elimine progresivamente para concentrar la atención en hospitales', 'Que se convierta en la puerta de entrada obligatoria al sistema de salud', 'Que dependa exclusivamente de la Red Complementaria privada', 'C', 'Referencia: Capítulo 4. El Modelo de Atención Integral de Salud Familiar Comunitario e Intercultural. Sección 4.4.2. Objetivos estratégicos. Página 56.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('1d678580-c4af-59c2-905f-4f37dcb70fb5', 'Según el manual, el objetivo estratégico 4.4.4 sobre excelencia en la prestación de servicios incorpora, en el primer y segundo nivel de atención, la figura de qué tipo de profesionales especializados?', 'Únicamente especialistas en medicina nuclear', 'Solo especialistas en trasplantes', 'Exclusivamente cirujanos cardiovasculares', 'Especialistas en Medicina Familiar y Comunitaria y Técnicos de Atención Primaria de Salud', 'D', 'Referencia: Capítulo 4. El Modelo de Atención Integral de Salud Familiar Comunitario e Intercultural. Sección 4.4.4. Objetivos estratégicos. Página 56.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('8c3de17e-4602-514e-84bc-8bd1160a3097', 'Según el manual, ¿cómo se define el principio de ''Universalidad'' del Modelo de Atención Integral de Salud?', 'La garantía de acceso a iguales oportunidades para el cuidado y atención integral de salud de toda la población, independientemente de nacionalidad, etnia, sexo o ingresos', 'La atención restringida a un grupo etario específico', 'La cobertura únicamente para la población de zonas urbanas', 'La atención exclusiva a personas afiliadas a un seguro privado', 'A', 'Referencia: Capítulo 4. El Modelo de Atención Integral de Salud Familiar Comunitario e Intercultural. Sección 4.5. Principios del MAIS. Universalidad. Página 57.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('4478ed5a-d7c2-5ffd-9429-bb18343d5990', 'Según el manual, ¿qué implica el principio de ''Integralidad'' del Modelo de Atención Integral de Salud?', 'Atender exclusivamente enfermedades agudas', 'Una visión multidimensional y biopsicosocial de la salud, actuando sobre riesgos y condiciones, e integrando promoción, prevención, recuperación, rehabilitación y cuidados paliativos', 'Centrarse únicamente en la atención hospitalaria de tercer nivel', 'Excluir la medicina ancestral y alternativa de la atención', 'B', 'Referencia: Capítulo 4. El Modelo de Atención Integral de Salud Familiar Comunitario e Intercultural. Sección 4.5. Principios del MAIS. Integralidad. Página 58.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('efde9989-6f8b-5b76-94fb-c18fee126cbc', 'Según el manual, ¿cómo se define el principio de ''Equidad'' dentro del MAIS?', 'El tratamiento idéntico sin considerar las necesidades particulares de cada persona', 'La atención basada únicamente en el orden de llegada, sin considerar vulnerabilidad', 'La eliminación de diferencias injustas en el estado de salud, acceso a la atención y ambientes saludables, con trato equitativo en el sistema de salud', 'La priorización exclusiva de la población con mayores recursos económicos', 'C', 'Referencia: Capítulo 4. El Modelo de Atención Integral de Salud Familiar Comunitario e Intercultural. Sección 4.5. Principios del MAIS. Equidad. Página 58.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('2943d4e7-9034-5d03-9460-0ff347ca7f75', 'Según el manual, ¿cómo se define el principio ''Desconcentrado'' del MAIS?', 'La centralización absoluta de todas las decisiones en el nivel nacional', 'La independencia total de cada distrito respecto a las normas nacionales', 'La eliminación completa de la autoridad sanitaria nacional', 'La transferencia de competencias de una entidad administrativa del nivel nacional a otra jerárquicamente dependiente, manteniendo la rectoría en el nivel nacional', 'D', 'Referencia: Capítulo 4. El Modelo de Atención Integral de Salud Familiar Comunitario e Intercultural. Sección 4.5. Principios del MAIS. Desconcentrado. Página 58.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('0b34980b-43e3-53dd-ab11-e9e65fe14116', 'Según el manual, ¿qué describe el principio de ''Continuidad'' del Modelo de Atención Integral de Salud?', 'El seguimiento al estado de salud de las personas y las familias, el control de los riesgos y factores determinantes para la salud a lo largo del proceso de atención', 'La suspensión de la atención una vez resuelto el problema de salud inmediato', 'La rotación constante del personal de salud entre distintas unidades sin continuidad del vínculo con la comunidad', 'La atención de un único episodio de enfermedad sin seguimiento posterior', 'A', 'Referencia: Capítulo 4. El Modelo de Atención Integral de Salud Familiar Comunitario e Intercultural. Sección 4.5. Principios del MAIS. Continuidad. Página 58.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('012e2883-11df-5e26-a51d-dbb1fb08307d', 'Según el manual, ¿cuáles son los componentes que hacen viable la operación y desarrollo del MAIS-FCI?', 'Solamente investigación y docencia', 'Provisión de servicios, organización, gestión y financiamiento del Sistema Nacional de Salud', 'Únicamente el componente de financiamiento', 'Exclusivamente infraestructura hospitalaria', 'B', 'Referencia: Capítulo 5. Componentes del Modelo de Atención Integral de Salud. Página 61.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('9d74e0d5-e4bb-5bfb-9883-24f079297a64', 'Según el glosario del manual, ¿qué describe el concepto de ''Interculturalidad en salud''?', 'La exclusión de las prácticas de medicina ancestral del sistema de salud', 'Un concepto exclusivo de las zonas urbanas', 'Un enfoque necesario de las intervenciones sanitarias que reconoce y articula la medicina formal con la medicina ancestral', 'La estandarización obligatoria de todas las prácticas médicas sin diferencias culturales', 'C', 'Referencia: Glosario de términos. Interculturalidad en salud. Página 205.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('22cf43ee-9f9b-5b3b-8f9c-8f9408dd6764', 'Según el manual, ¿qué implica el principio de ''Garantía de los derechos de las y los ciudadanos'' del MAIS?', 'Reducir la corresponsabilidad de la ciudadanía en el cuidado de su propia salud', 'Concentrar la atención en un solo grupo etario', 'Limitar el acceso a servicios de salud únicamente a quienes tengan capacidad de pago', 'Generar condiciones para el desarrollo de una vida saludable y el acceso universal a servicios de salud integrales, de calidad, eliminando barreras de acceso', 'D', 'Referencia: Capítulo 4. El Modelo de Atención Integral de Salud Familiar Comunitario e Intercultural. Sección 4.5. Principios del MAIS. Garantía de derechos. Página 57.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('81cb8864-e934-52b3-ac91-f520a5174214', 'Según el manual, el objetivo estratégico 4.4.1 plantea una reorientación del enfoque de atención. ¿Cuál es esta reorientación?', 'Del enfoque curativo centrado en la enfermedad y el individuo, hacia un enfoque de producción y cuidado de la salud sustentado en la estrategia de APS', 'Del enfoque comunitario hacia un enfoque exclusivamente hospitalario', 'De la atención pública hacia la atención exclusivamente privada', 'De la promoción de la salud hacia un enfoque netamente farmacológico', 'A', 'Referencia: Capítulo 4. El Modelo de Atención Integral de Salud Familiar Comunitario e Intercultural. Sección 4.4.1. Objetivos estratégicos. Página 56.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('cb0ba24b-dc6b-5d30-a1c1-93674aa4e0cd', 'Según el manual, el principio relacionado con el uso racional de los recursos, orientado a la satisfacción de las necesidades de las personas, ¿a qué apunta principalmente?', 'A destinar todos los recursos exclusivamente a infraestructura', 'A garantizar el uso adecuado y un mayor rendimiento de los recursos, con enfoque en la eficiencia', 'A eliminar cualquier forma de planificación presupuestaria', 'A maximizar el gasto sin considerar los resultados obtenidos', 'B', 'Referencia: Capítulo 4. El Modelo de Atención Integral de Salud Familiar Comunitario e Intercultural. Sección 4.5. Principios del MAIS. Página 58.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('351c4979-cb93-5dce-bb31-9699fe415b7e', 'Según el manual, dentro de los principios del MAIS, ¿qué cambio se plantea respecto a la relación entre el equipo de salud y la persona atendida?', 'Se elimina cualquier tipo de relación entre el equipo de salud y la persona', 'Se mantiene sin cambios la relación jerárquica institución-paciente del modelo anterior', 'Se cambia de la relación institución-paciente del modelo anterior a la relación equipo de salud-persona sujeto de derechos o ciudadano', 'Se limita la relación exclusivamente a la atención de urgencias', 'C', 'Referencia: Capítulo 4. El Modelo de Atención Integral de Salud Familiar Comunitario e Intercultural. Sección 4.5. Principios del MAIS. Página 58.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('634b3863-f3fc-5a68-9155-3e621b4fd8fe', 'Según el manual, dentro de los principios del MAIS, ¿qué tipo de resultados debe buscar fundamentalmente la gestión y atención del modelo?', 'Exclusivamente resultados financieros de rentabilidad', 'Solo resultados de reducción de personal', 'Únicamente resultados institucionales de producción de consultas', 'Resultados de impacto social, para mejorar la calidad de vida de la población', 'D', 'Referencia: Capítulo 4. El Modelo de Atención Integral de Salud Familiar Comunitario e Intercultural. Sección 4.5. Principios del MAIS. Página 58.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('f30fa5e1-c89f-5faa-a762-45cdfc17b049', 'Según el manual, el objetivo estratégico 4.4.5 propone implementar qué sistema para fortalecer los procesos de atención, gestión y toma de decisiones?', 'El Sistema Integrado de Telecomunicaciones y el Sistema Único de Información', 'Un sistema exclusivo de facturación privada', 'Un sistema de vigilancia policial en los establecimientos de salud', 'Un sistema de transporte aéreo exclusivo para el personal directivo', 'A', 'Referencia: Capítulo 4. El Modelo de Atención Integral de Salud Familiar Comunitario e Intercultural. Sección 4.4.5. Objetivos estratégicos. Página 57.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('0381b633-3163-573e-a31d-48996cda9803', 'Según el manual, el objetivo estratégico 4.4.6 busca impulsar la participación plena de la comunidad. ¿Cuál es el sentido de esta participación según el manual?', 'Excluir a los colectivos organizados de cualquier proceso de evaluación', 'Facilitar el ejercicio de derechos y responsabilidades en salud, para que la comunidad se constituya en sujeto activo de la construcción y cuidado de la salud', 'Limitar la participación exclusivamente a la fase de financiamiento', 'Reducir el rol de la comunidad a la simple recepción pasiva de servicios', 'B', 'Referencia: Capítulo 4. El Modelo de Atención Integral de Salud Familiar Comunitario e Intercultural. Sección 4.4.6. Objetivos estratégicos. Página 57.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('e1fc02da-28f0-5239-a5f6-afad322e030b', 'Según el manual, ¿qué describe el principio ''Participativo'' del MAIS?', 'La participación limitada únicamente al personal médico', 'La ausencia de mecanismos de corresponsabilidad y autocuidado', 'Mecanismos que contribuyan a la participación activa de las personas y colectivos en la toma de decisiones sobre prioridades, asignación y uso de recursos', 'La exclusión de la comunidad de cualquier decisión sobre los recursos de salud', 'C', 'Referencia: Capítulo 4. El Modelo de Atención Integral de Salud Familiar Comunitario e Intercultural. Sección 4.5. Principios del MAIS. Participativo. Página 58.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('45518abe-7286-582a-92d0-5a5495027a5e', 'Según el manual, el objetivo estratégico 4.4.7 se orienta al fortalecimiento de qué proceso, incorporando experiencias comunitarias?', 'La privatización de los laboratorios clínicos', 'La construcción exclusiva de nuevos hospitales', 'La eliminación del sistema de referencia y contrarreferencia', 'La vigilancia epidemiológica', 'D', 'Referencia: Capítulo 4. El Modelo de Atención Integral de Salud Familiar Comunitario e Intercultural. Sección 4.4.7. Objetivos estratégicos. Página 57.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('0a4c4ac7-0768-5458-b201-56137a685a62', 'Caso clínico: Un equipo de salud del primer nivel debe clasificar a un usuario de 16 años dentro de los ciclos de vida establecidos por el MAIS-FCI. Según la Tabla 1 del manual (Ciclos de Vida), ¿en qué grupo de edad se clasifica a este usuario?', 'Adolescencia, segunda etapa (15 a 19 años)', 'Adultos/as, adulto joven (20 a 39 años)', 'Niñez, 5 a 9 años', 'Adolescencia, primera etapa (10 a 14 años)', 'A', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.1.1. Grupos de población. Tabla 1. Ciclos de Vida. Página 62.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('940c0778-5dd6-5a84-9e36-cde54bb40309', 'Según la Tabla 1 del manual, ¿a partir de qué edad se clasifica a una persona como ''adulto/a mayor''?', 'A partir de los 50 años', 'Más de 65 años', 'A partir de los 60 años', 'A partir de los 40 años', 'B', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.1.1. Grupos de población. Tabla 1. Ciclos de Vida. Página 62.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('9ebfbe45-5713-5592-ba62-b98e21471ff4', 'Según el manual, además de adultos mayores, mujeres embarazadas, niños, niñas y adolescentes, ¿qué otros grupos se consideran de atención prioritaria de acuerdo al artículo 35 de la Constitución?', 'Exclusivamente los estudiantes universitarios', 'Únicamente los trabajadores del sector agrícola', 'Personas con discapacidad y personas privadas de la libertad', 'Solo el personal administrativo del MSP', 'C', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.1.1. Grupos de población. Grupos de atención prioritaria. Página 62.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('8032d8b2-8bf9-5682-911d-40cb4636de92', 'Según el manual, ¿cuál es el propósito central de un Conjunto de Prestaciones de Salud (CPS)?', 'Limitar la atención únicamente a la fase curativa de la enfermedad', 'Eliminar la necesidad de actualización periódica de los servicios', 'Reducir el número de atenciones disponibles para la población', 'Contribuir a la transformación de un derecho declarado a la salud en un derecho objetivable a determinadas acciones de promoción, prevención, atención y rehabilitación', 'D', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.1.2. Conjunto de prestaciones por ciclos de vida. Página 63.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('38879136-bcbe-5b5e-8db9-87fe8b0fe965', 'Caso clínico: El equipo de atención integral de salud identifica que un adolescente presenta un problema de salud cuyo origen se relaciona con conflictos dentro de su hogar, que afectan tanto a él como a otros miembros de su hogar. Según el manual, ¿en qué escenario de atención debe enfocarse principalmente la intervención del equipo de salud en este caso?', 'Atención Familiar', 'Atención al Ambiente o Entorno Natural', 'Atención Individual exclusivamente', 'Atención a la Comunidad exclusivamente', 'A', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.1.3. Escenarios de la Atención. Atención Familiar. Página 64.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('5875b0d6-d049-5982-862e-ee8de63dd3e8', 'Según el manual, ¿cuáles son las modalidades bajo las cuales el MAIS-FCI organiza la atención integral?', 'Solamente atención virtual', 'Atención extramural o comunitaria, intramural, en establecimientos móviles y prehospitalaria', 'Únicamente atención intramural', 'Exclusivamente atención domiciliaria privada', 'B', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.1.4. Modalidades de atención. Página 65.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('c353a548-b38e-557e-8a85-53ae533fdf74', 'Según el manual, ¿qué caracteriza a la atención intramural o en la unidad de salud?', 'Se brinda exclusivamente fuera de la unidad de salud, en el domicilio del usuario', 'Se limita exclusivamente a actividades de investigación, sin atención directa a usuarios', 'Es la que se brinda en la unidad de salud implementando el conjunto de prestaciones por ciclos de vida, bajo normas, protocolos y guías clínicas establecidas por la ASN', 'No requiere el cumplimiento de ninguna norma o protocolo', 'C', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.1.4. Modalidades de atención. Atención intramural. Página 65.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('a6b19ec5-9020-5402-beea-f80b5a62d132', 'Según el manual, ¿cuál es el objetivo principal de la atención extramural o comunitaria?', 'Limitarse a la atención de pacientes hospitalizados', 'Realizar exclusivamente cirugías de alta complejidad', 'Sustituir completamente a la atención intramural', 'El Cuidado de la Salud a través de medidas orientadas a la identificación y control de riesgos a nivel individual, familiar, comunitario y del entorno', 'D', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.1.4. Modalidades de atención. Atención extramural o comunitaria. Página 65.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('d239ef78-7fad-5e40-8301-d5ea4a55a24e', 'Según la Tabla 3 del manual, ¿cómo se define la Visita Domiciliaria dentro del MAIS-FCI?', 'El encuentro o acercamiento del equipo de salud al domicilio del usuario, familia y/o comunidad, para la valoración y decisión de un plan de intervención', 'Un procedimiento exclusivamente administrativo sin contacto directo con la familia', 'Una actividad realizada únicamente en el tercer nivel de atención', 'Una visita que se realiza solo cuando la familia lo solicita expresamente por escrito', 'A', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.1.5. Estrategias y herramientas. Tabla 3. Visita Domiciliaria. Página 70.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('7002b856-b323-50e7-afad-7cc6f9268226', 'Según la Tabla 4 del manual, ¿cuáles son los dos objetivos fundamentales de la Ficha Familiar?', 'Reemplazar completamente a la historia clínica individual', 'Medir las condiciones de vida y medir los determinantes sociales de salud', 'Servir exclusivamente como instrumento de facturación', 'Registrar únicamente los datos económicos de la familia', 'B', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.1.5. Estrategias y herramientas. Tabla 4. Ficha Familiar. Página 77.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('56f71b78-0fde-5436-abad-8395a45ffa6d', 'Según el manual, ¿cuál es el instrumento del MAIS-FCI que complementa, sin reemplazar, a la historia clínica individual?', 'La Guía de supervisión para equipos de salud', 'El Sistema Único de Información', 'La Ficha Familiar', 'El Tarjetero de citas', 'C', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.1.5. Estrategias y herramientas. Tabla 4. Ficha Familiar. Página 77.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('3e772fe5-b901-51e8-b8ea-80e5ca61ccb3', 'Según el manual, ¿cuántos criterios de carácter nacional para la categorización del tipo de riesgo ha establecido el nivel nacional en la Ficha Familiar?', '25 criterios', '5 criterios', '10 criterios', '18 criterios', 'D', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.1.5. Estrategias y herramientas. Tabla 4. Ficha Familiar. Página 77.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('2076f5d6-9196-5845-9990-9cff04bc9250', 'Caso clínico: Al aplicar la Ficha Familiar en una vivienda, el equipo de salud constata que el jefe de familia no se encuentra presente en el momento de la visita. Según el manual, ¿de quién se obtendrá la información en este caso, si no se encuentra el jefe de familia?', 'Se obtendrá la información de una persona mayor de 15 años presente en la vivienda', 'Se cancelará la visita domiciliaria de forma definitiva', 'No se registrará ningún dato hasta que regrese el jefe de familia', 'Se obtendrá exclusivamente de un vecino de la vivienda', 'A', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.1.5. Estrategias y herramientas. Tabla 4. Ficha Familiar. Página 79.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('79f4a079-1f14-54a8-bee5-d1bc641866a3', 'Según el manual, ¿cómo se define el concepto de ''familia'' para efectos de la aplicación de la Ficha Familiar?', 'Exclusivamente a un matrimonio legalmente constituido sin hijos', 'Al grupo de personas que tienen vínculos sanguíneos, legales, culturales y/o afectivos, que comparten espacios colectivos como el techo común y prácticas colectivas como la alimentación de una olla común', 'Únicamente a las personas que comparten el mismo apellido', 'Solo a los residentes registrados en el censo poblacional', 'B', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.1.5. Estrategias y herramientas. Tabla 4. Ficha Familiar. Página 79.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('3aa1329e-164d-52f3-bc60-e8d1878b7384', 'Según el manual, ¿cómo se describe el escenario de ''Atención a la Comunidad'' dentro del MAIS-FCI?', 'Como un escenario donde no se permite la participación de sujetos sociales', 'Como un escenario exclusivamente hospitalario de tercer nivel', 'Como el escenario inmediato donde se desarrolla la vida de las personas y familias, donde interactúan condiciones sociales, económicas y ambientales que generan potencialidades o riesgos para la salud', 'Como un espacio limitado únicamente a la atención individual', 'C', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.1.3. Escenarios de la Atención. Atención a la Comunidad. Página 64.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('3f03d59a-b9fe-5fa8-8fbe-06adea143775', 'Caso clínico: Durante una visita domiciliaria, el equipo de salud identifica que una familia presenta problemas graves en su función y organización familiar, además de problemas socioeconómicos que requieren una intervención urgente. Según el manual, ¿qué conducta corresponde al equipo de salud ante el descubrimiento de una familia de riesgo socio-sanitario como la descrita?', 'Esperar hasta la siguiente visita domiciliaria programada, sin ninguna acción inmediata', 'Referir automáticamente a la familia al tercer nivel de atención sin evaluación previa', 'Ignorar el hallazgo, ya que no compete al equipo de salud del primer nivel', 'Convocar a una reunión urgente del equipo de salud para evaluar el caso y decidir la intervención pertinente', 'D', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.1.5. Estrategias y herramientas. Tabla 3. Visita Domiciliaria. Página 71.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('26ecf3ac-f862-52cb-b847-67f7fd88d562', 'Según el manual, ¿qué tipo de acciones incorpora el escenario de ''Atención al Ambiente o Entorno Natural''?', 'Estrategias y acciones orientadas al cuidado ambiental, prevención, promoción de estilos de vida saludables y educación sobre riesgos ambientales', 'Únicamente la construcción de nuevas unidades de salud', 'Solo la atención odontológica escolar', 'Exclusivamente la vacunación de la población', 'A', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.1.3. Escenarios de la Atención. Atención al Ambiente o Entorno Natural. Página 64.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('d5533266-71f3-5cd6-9596-f35e5ddd014a', 'Según el manual, ¿en qué se debe basar la atención individual dentro del escenario descrito?', 'Exclusivamente en la aplicación de exámenes de laboratorio', 'En el respeto y reconocimiento, tanto del equipo de salud como de la persona, de los derechos y responsabilidades en salud, siendo un espacio interactivo y de aprendizaje mutuo', 'En una relación estrictamente jerárquica donde el usuario no participa en las decisiones', 'Únicamente en la prescripción de medicamentos sin valoración integral', 'B', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.1.3. Escenarios de la Atención. Atención Individual. Página 64.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('b9e678b4-5174-5c19-989e-0073cadbe1e5', 'Según el manual, ¿cuáles son las prestaciones que el MAIS-FCI reconoce para lograr integralidad en la atención?', 'Únicamente Promoción y Prevención', 'Solamente Recuperación y Rehabilitación', 'Promoción, Prevención, Recuperación, Rehabilitación y Cuidados Paliativos', 'Exclusivamente Cuidados Paliativos', 'C', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.1.2. Conjunto de prestaciones por ciclos de vida. Página 64.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('97ef6c90-7fe8-586c-8f7f-135b6d946eea', 'Según el manual, ¿qué característica debe cumplir el conjunto de prestaciones de salud (CPS) respecto a su vigencia en el tiempo?', 'Solo puede modificarse cada 20 años', 'No requiere ningún tipo de revisión posterior a su publicación inicial', 'Debe mantenerse fijo e inmutable de forma indefinida', 'Debe ser actualizado periódicamente, involucrando un monitoreo de las necesidades de salud que por derecho deben ser cubiertas', 'D', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.1.2. Conjunto de prestaciones por ciclos de vida. Página 63.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('03204640-2983-53e0-8fbe-14948512cfac', 'Según el manual, ¿qué porcentaje de las necesidades de salud de la población debe resolver el primer nivel de atención, según lo establecido en el Acuerdo Ministerial No. 1203?', 'El 80%', 'El 10%', 'El 30%', 'El 50%', 'A', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.2.1. Niveles de Atención. Página 85.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('8d29df42-2139-56ef-bb86-7da9e28daaf5', 'Caso clínico: Un paciente es referido desde el primer nivel de atención para recibir manejo especializado ambulatorio que requiere tecnología sanitaria de mayor complejidad, no resuelta en el primer nivel. Según el manual, ¿a qué nivel de atención corresponde continuar con este caso?', 'A ningún nivel, ya que el sistema no contempla referencia entre niveles', 'Al segundo nivel de atención, que da continuidad a la atención iniciada en el primer nivel para los casos no resueltos que requieren atención especializada', 'Al primer nivel de atención únicamente', 'Al nivel de atención prehospitalaria', 'B', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.2.1. Niveles de Atención. Segundo Nivel de Atención. Página 86.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('747dedb1-72be-5789-bc6e-111c7bf1ba59', 'Según el manual, ¿qué caracteriza al tercer nivel de atención?', 'No requiere personal especializado', 'Se limita a la atención prehospitalaria de urgencias', 'Corresponde a establecimientos que prestan servicios ambulatorios y hospitalarios de especialidad y especializados, con tecnología de punta y subespecialidades reconocidas por la ley', 'Resuelve exclusivamente los problemas de salud de menor complejidad', 'C', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.2.1. Niveles de Atención. Tercer Nivel de Atención. Página 86.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('2f2739de-ce07-5af9-8145-6e1e7de26e00', 'Según el manual, ¿qué función cumple el cuarto nivel de atención?', 'Reemplaza completamente al primer nivel de atención', 'Está disponible en cualquier establecimiento privado sin autorización especial', 'Se encarga exclusivamente de la atención primaria comunitaria', 'Concentra la experimentación clínica, preregistro o procedimientos cuya evidencia no es suficiente para instaurarse en la población, pero que han demostrado buenos resultados casuísticamente', 'D', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.2.1. Niveles de Atención. Cuarto Nivel de Atención. Página 86.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('10a32ea1-d54b-5bb5-8deb-8468b178a27c', 'Caso clínico: Un establecimiento de salud está categorizado como I-3 dentro de la tipología nacional. Según la Tabla 6 del manual, ¿a qué tipo de establecimiento corresponde esta categoría?', 'Centro de salud – A', 'Puesto de salud', 'Consultorio general', 'Hospital Básico', 'A', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.2.1. Tabla 6. Tipología de las Unidades Operativas del Sistema Nacional de Salud. Página 87.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('cd3d8755-2de6-5d9d-9424-739cc48326ca', 'Según la Tabla 6 del manual, ¿qué categoría corresponde al ''Hospital General'' dentro de la tipología nacional?', 'III-2', 'II-5', 'II-3', 'I-5', 'B', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.2.1. Tabla 6. Tipología de las Unidades Operativas del Sistema Nacional de Salud. Página 87.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('a709f80f-5cd6-52f0-8fd3-a731f9eaf8b9', 'Según la Tabla 6 del manual, ¿qué nombre recibe el establecimiento categorizado como III-3?', 'Centro de alta Subespecialidad', 'Centros especializados', 'Hospital de Especialidades', 'Hospital especializado', 'C', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.2.1. Tabla 6. Tipología de las Unidades Operativas del Sistema Nacional de Salud. Página 87.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('e751c2be-d682-5394-b7cb-90efd3c66d1d', 'Según la Tabla 6 del manual, ¿qué categoría corresponde a la ''Unidad de atención Prehospitalaria de transporte y soporte vital avanzado''?', 'IV-1', 'APH-3', 'APH-1', 'APH-2', 'D', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.2.1. Tabla 6. Tipología de las Unidades Operativas del Sistema Nacional de Salud. Página 87.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('47061662-5815-554a-8a23-e8f08e9c22d8', 'Caso clínico: Un distrito de salud debe conformar un Equipo de Atención Integral de Salud para una comunidad rural de 2.000 habitantes. Según el manual, ¿cuál es el estándar de conformación de un equipo de atención integral de salud a nivel rural?', 'Un médico/a, una enfermera/o y un TAPS por cada 1.500 a 2.500 habitantes', 'Un médico/a, una enfermera/o y un TAPS por cada 4.000 habitantes', 'Cinco médicos por cada 500 habitantes', 'No existe un estándar definido para zonas rurales', 'A', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.2.2. Organización de los equipos de atención integral de salud. Página 89.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('956cbda3-9ecc-59c4-9917-0a41e4c3a690', 'Según el manual, ¿cuál es el estándar de conformación de un equipo de atención integral de salud a nivel urbano?', 'Solo un TAPS, sin médico ni enfermera', 'Un médico/a, una enfermera/o y un TAPS por cada 4.000 habitantes', 'Un médico/a, una enfermera/o y un TAPS por cada 1.500 habitantes', 'Diez médicos por cada 10.000 habitantes', 'B', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.2.2. Organización de los equipos de atención integral de salud. Página 89.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('417bd16b-42cc-527a-9d1e-414cefd1a195', 'Según el manual, ¿cuántas zonas de planificación, distritos y circuitos se establecen en la nueva organización territorial desconcentrada del país?', '24 zonas, 24 distritos y 100 circuitos', '5 zonas, 50 distritos y 500 circuitos', '9 zonas, 140 distritos y 1134 circuitos', '1 zona nacional única sin distritos ni circuitos', 'C', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.2.4. La articulación territorial de la red pública y complementaria de salud en zonas, distritos y circuitos. Página 91.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('14a71b3d-36d2-5290-a31c-f871afb8f8bb', 'Según el manual, ¿cuál de los siguientes es uno de los atributos esenciales que deben cumplir las Redes Integradas de Servicios de Salud?', 'La concentración de todos los servicios exclusivamente en el nivel central', 'La ausencia total de mecanismos de coordinación entre niveles', 'La eliminación del apoyo al autocuidado del usuario', 'Una cartera de servicios disponibles suficiente para responder a las necesidades de salud de la población, incluyendo promoción, prevención, diagnóstico, atención curativa, rehabilitadora y paliativa', 'D', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.2.3. Organización y funcionamiento de la Red Pública Integral de Salud y Complementaria. Página 90.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('cd77438b-eaf2-5b67-ab08-4aae5cc22099', 'Según la Tabla 7 del manual, ¿qué categoría corresponde al Centro de Diagnóstico Integral de alta complejidad?', 'CDI-3', 'CDI-2', 'CDI-1', 'CDI-0', 'A', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.2.1. Tabla 7. Página 87.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('e72fec33-a922-566e-babf-dd155327afa2', 'Según el manual, ¿en qué debe basarse principalmente el desarrollo armónico y las tareas compartidas de los equipos de atención integral de salud del primer nivel, en lugar de una jerarquía vertical?', 'En decisiones tomadas únicamente por el nivel central sin participación del equipo local', 'En la división funcional del trabajo y las responsabilidades compartidas de acuerdo a la capacitación técnica de los profesionales', 'En el nivel de remuneración de cada profesional', 'En la antigüedad exclusiva del personal dentro de la institución', 'B', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.2.2. Organización de los equipos de atención integral de salud. Página 89.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('009189c0-e378-5c99-85ed-29222bd70556', 'Según el glosario del manual, ¿cómo se define el ''Equipo Integral de Salud''?', 'Un grupo que actúa sin ninguna coordinación con la comunidad', 'Un grupo que trabaja exclusivamente en el ámbito hospitalario de tercer nivel', 'Un grupo interdisciplinario de recursos humanos de la salud que realiza actividades de promoción, prevención, tratamiento, rehabilitación y cuidados paliativos, con apoyo de los recursos de la comunidad', 'Un grupo conformado únicamente por médicos especialistas', 'C', 'Referencia: Glosario de términos. Equipo Integral de Salud. Página 204.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('faa15deb-6ef9-5c46-b148-4de55770df3e', 'Según el glosario del manual, ¿cómo se define el Primer Nivel de Atención?', 'Como el nivel que concentra exclusivamente la experimentación clínica', 'Como un nivel opcional que la población puede omitir sin consecuencias', 'Como el nivel exclusivo para la atención de emergencias graves', 'Como la organización de los recursos que permiten resolver las necesidades básicas y/o más frecuentes de la salud de una población, con tecnologías simples accesibles de forma inmediata', 'D', 'Referencia: Glosario de términos. Primer Nivel de Atención. Página 206.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('8512d4c1-40c0-5d82-a90f-264e0fbe07bc', 'Caso clínico: Una campaña de salud pública se dirige a personas ya diagnosticadas con hipertensión arterial, buscando evitar complicaciones antes de que estas se presenten. Según el glosario del manual, ¿a qué nivel de prevención corresponde esta intervención?', 'Prevención secundaria, que actúa una vez que la enfermedad ya apareció', 'El manual no reconoce niveles de prevención', 'Prevención primaria, ya que combate la enfermedad antes de que se presente', 'Prevención terciaria, cuando la enfermedad ya siguió su curso completo', 'A', 'Referencia: Glosario de términos. Prevención. Página 206.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('61ca950c-9795-524d-b9d1-f10254542102', 'Según el glosario del manual, ¿cómo se definen los ''Determinantes de la salud''?', 'Como factores exclusivamente genéticos e inmodificables', 'Como los factores ambientales, económicos, culturales, entre otros, que influyen en la salud de los individuos o poblaciones', 'Como sinónimo exclusivo de la infraestructura hospitalaria', 'Como un concepto que no tiene relación con las condiciones sociales', 'B', 'Referencia: Glosario de términos. Determinantes de la salud. Página 204.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('bdad2997-cb09-5c44-895a-a75fa3cef688', 'Según el glosario del manual, ¿qué describe el concepto de ''Accesibilidad'' en el sistema de salud?', 'El costo exclusivo de los medicamentos de patente', 'La cantidad de camas hospitalarias disponibles en un distrito', 'Las características de la organización para garantizar el principio de equidad en la eliminación de barreras (estructurales, culturales) para la participación en el sistema de salud', 'La distancia física entre dos hospitales de tercer nivel', 'C', 'Referencia: Glosario de términos. Accesibilidad. Página 203.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('edbea3ae-9214-596c-ac21-aaff1dd5d6fb', 'Según el glosario del manual, ¿para qué se utiliza el ''Apgar Familiar''?', 'Para calcular el índice de masa corporal familiar', 'Para evaluar la condición del recién nacido inmediatamente después del parto', 'Para medir la presión arterial de los miembros de la familia', 'Para detectar el grado de funcionalidad (o disfunción) de la familia', 'D', 'Referencia: Glosario de términos. Apgar Familiar. Página 203.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('469ce081-29e4-5ed6-9b1c-134dbf790d13', 'Según el manual, citando a la OPS (1999), ¿qué es el Análisis Situacional de Salud (ASIS)?', 'Procesos analítico-sintéticos que permiten caracterizar, medir y explicar el perfil de salud-enfermedad de una población, incluyendo sus determinantes', 'Un formulario exclusivo para el registro de vacunas aplicadas', 'Un examen de laboratorio individual', 'Un instrumento exclusivamente financiero de las unidades de salud', 'A', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.3.1. Herramientas de diagnóstico y monitoreo. Análisis situacional de Salud (ASIS). Página 98.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('17275503-94f0-5c2e-bc24-d858aa4f09de', 'Según el manual, ¿en qué instrumento normativo se establece la Metodología de Gobierno por Resultados (GPR) de cumplimiento obligatorio para las instituciones de la Administración Pública Central?', 'En un acuerdo verbal sin respaldo documental', 'En el Acuerdo Presidencial 1002', 'En una resolución exclusiva de un gobierno autónomo descentralizado municipal', 'En un contrato privado entre el MSP y una consultora internacional', 'B', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.3. Componente de Gestión. Gestión basada en la metodología de Gobierno por Resultados (GPR). Página 97.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('cd1a52af-f78b-5833-984a-b47d5e994205', 'Según el manual, ¿qué describe el concepto de ''Sala situacional'' dentro de las herramientas de diagnóstico y monitoreo del MAIS-FCI?', 'Una sala destinada únicamente al almacenamiento de medicamentos', 'Un espacio exclusivo para reuniones administrativas sin relación con la salud pública', 'Un espacio, virtual y matricial, de convergencia para el análisis de factores determinantes, la búsqueda de soluciones viables y el monitoreo de resultados', 'Un instrumento que reemplaza por completo a la vigilancia epidemiológica tradicional sin ninguna relación con ella', 'C', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.3.1. Herramientas de diagnóstico y monitoreo. Sala situacional. Página 99.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('23ff2e46-389b-59b5-b1ae-e779a2c17bbb', 'Según el manual, citando el artículo 366 de la Constitución, ¿con base en qué criterios se distribuirán los recursos públicos destinados a salud?', 'Únicamente según el nivel de ingresos fiscales de cada provincia', 'Exclusivamente en función de la cercanía geográfica a la capital', 'Solo en función de la antigüedad de los establecimientos de salud', 'Con base en criterios de población y en las necesidades de salud', 'D', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.4. Componente de Financiamiento. Art. 366 de la Constitución. Página 104.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('222baa47-ae4e-5adf-8147-2fa1de4a4176', 'Según el manual, ¿cómo se clasifica al Ministerio de Salud Pública en el marco del componente de financiamiento y gestión?', 'Como una Institución de Tipología 2, es decir, altamente desconcentrada con baja descentralización', 'Como una institución de carácter exclusivamente privado', 'Como una institución completamente centralizada sin ningún grado de desconcentración', 'Como una institución sin ninguna relación con el proceso de Transformación Democrática del Estado', 'A', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.4. Componente de Financiamiento. Página 104.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('68d2935e-cad4-5189-a36f-03f0feca4dbd', 'Según el manual, ¿cuáles son las tres funciones fundamentales del Primer Nivel de Atención?', 'Realizar únicamente cirugías de alta complejidad', 'Ser la puerta de entrada al sistema, la responsabilidad del cuidado de la salud individual, familiar y comunitaria, y la síntesis de la información', 'Concentrarse exclusivamente en la investigación clínica experimental', 'Administrar exclusivamente los recursos financieros del nivel central', 'B', 'Referencia: Capítulo 6. Fases y herramientas para la implementación del MAIS-FCI. Sección 6.2. Funciones de los servicios de salud en el primer nivel de atención. Página 112.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('40ed3d3d-a54f-5c74-99a9-c048010e8fba', 'Caso clínico: La Unidad de Gestión Distrital debe asignar una población determinada a un establecimiento de salud del primer nivel. Según el manual, ¿qué criterios debe considerar la Unidad de Gestión Distrital para esta asignación?', 'Solo la cantidad de personal médico disponible sin considerar la población territorial', 'Exclusivamente la cercanía a la vivienda del director distrital', 'La tipología de la unidad, la población de acuerdo al censo y proyecciones del INEC, y la aplicación del principio de equidad', 'Únicamente el número de camas disponibles', 'C', 'Referencia: Capítulo 6. Fases y herramientas para la implementación del MAIS-FCI. Sección 6.2. Funciones de los servicios de salud en el primer nivel de atención. Página 112.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('d2cdde16-5075-51b4-9303-0df1c4d3fea5', 'Según el manual, ¿cuántas supervisiones al año, como mínimo, deben recibir los equipos de salud del primer nivel?', 'No se establece un número mínimo de supervisiones', 'Una supervisión anual', 'Seis supervisiones al año', 'Tres supervisiones al año', 'D', 'Referencia: Capítulo 6. Fases y herramientas para la implementación del MAIS-FCI. Sección 6.6. Otros criterios a ser considerados. Página 117.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('ee17f235-50e4-5312-be6d-f741623f1b26', 'Según el manual, ¿qué tipo de actividades desarrolla el Técnico de Atención Primaria en Salud (TAPS) como parte del equipo integral de salud?', 'Actividades de promoción de la salud, prevención de riesgos y fortalecimiento de la participación comunitaria', 'Actividades exclusivas de cirugía ambulatoria', 'Actividades limitadas a la interpretación de estudios de imagen', 'Actividades exclusivamente administrativas de facturación hospitalaria', 'A', 'Referencia: Capítulo 6. Fases y herramientas para la implementación del MAIS-FCI. Sección 6.6. Otros criterios a ser considerados. Página 117.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('96dc66d3-1f2a-536b-8131-c98aa81a64f1', 'Caso clínico: El equipo de salud implementa acciones dirigidas a grupos desagregados por género, etnia y ciclo de vida para mantener la salud de la población, sin que exista todavía un problema de enfermedad manifiesto. Según el manual, ¿a qué nivel del campo de acción de los equipos de salud corresponde esta actividad?', 'Nivel familiar y comunitario', 'Nivel epidemiológico', 'Nivel de enfermedad', 'Nivel social', 'B', 'Referencia: Capítulo 6. Fases y herramientas para la implementación del MAIS-FCI. Sección 6.5. Campo de acción de los Equipos de salud. Nivel epidemiológico. Página 116.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('9588a5c6-7af7-5750-ad16-c73ba99a8fee', 'Según el manual, ¿cuál de los siguientes es uno de los principales productos que deben obtener los equipos de salud del primer nivel para la evaluación de su desempeño?', 'La construcción de nuevos hospitales de cuarto nivel', 'Un número fijo de cirugías cardiovasculares realizadas', 'Salas situacionales implementadas y actualizadas de manera periódica con participación de la comunidad', 'La eliminación de los comités de usuarios', 'C', 'Referencia: Capítulo 6. Fases y herramientas para la implementación del MAIS-FCI. Sección 6.7. Productos de los equipos de salud de primer nivel. Página 117.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('ec89228c-183b-5078-96b6-1d2e976e9cdc', 'Caso clínico: Un paciente con un problema de salud complejo requiere una intervención quirúrgica de alta severidad y cuidados intensivos, no disponibles en el establecimiento de primer nivel donde inicialmente fue atendido. Según el manual, considerando la tipología de establecimientos, ¿a qué nivel de atención corresponde referir a este paciente?', 'Al primer nivel, categoría I-1 (Puesto de salud)', 'A ningún nivel, ya que el manual no contempla la referencia de casos complejos', 'Al segundo nivel, categoría II-1 (Consultorio de especialidad)', 'Al tercer nivel de atención, dado que resuelve problemas de alta complejidad, con recursos de tecnología de punta e intervención quirúrgica de alta severidad', 'D', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.2.1. Niveles de Atención. Tercer Nivel de Atención. Tabla 6. Página 86-87.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('2959077c-29e5-59df-aa53-273beeb1bbf9', 'Caso clínico: Un equipo de salud identifica en su comunidad a una mujer embarazada de 32 años y a un adulto mayor de 70 años, ambos requiriendo seguimiento por parte del equipo de atención integral. Según el manual, ¿qué característica comparten ambos usuarios en el marco del MAIS-FCI?', 'Ambos corresponden a grupos de atención prioritaria establecidos en la Constitución', 'Solo el adulto mayor corresponde a un grupo de atención prioritaria', 'Ninguno de los dos corresponde a un grupo de atención prioritaria', 'Solo la mujer embarazada corresponde a un grupo de atención prioritaria', 'A', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.1.1. Grupos de población. Grupos de atención prioritaria. Página 62.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('be04c258-5aa8-5ce8-8342-913e79087910', 'Caso clínico: Un distrito de salud decide transferir determinadas competencias administrativas del nivel nacional hacia el nivel zonal y distrital, manteniendo la rectoría técnica en el nivel nacional. Según el manual, ¿qué principio del MAIS y qué característica de la gestión sanitaria describen mejor esta situación?', 'El principio de continuidad y la gestión exclusivamente hospitalaria', 'El principio desconcentrado y la gestión sanitaria desconcentrada por transferencia de competencias del nivel central a los niveles zonales y distritales', 'El principio de equidad y la gestión basada únicamente en gastos históricos', 'El principio de universalidad y la gestión centralizada', 'B', 'Referencia: Capítulo 4. Sección 4.5. Principios del MAIS. Desconcentrado. Página 58. Capítulo 5. Sección 5.3. Componente de Gestión. Página 97.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('c9ee60a5-7adc-503d-b0de-abd907696b16', 'Caso clínico: Durante una visita domiciliaria de rutina, el equipo de salud del primer nivel recopila información sobre la composición, riesgos y determinantes sociales de una familia de su zona de cobertura. Según el manual, ¿qué instrumento se utiliza específicamente para registrar esta información obtenida en la visita domiciliaria?', 'El Tarjetero de citas', 'El Acuerdo Ministerial 1203', 'La Ficha Familiar', 'El Sistema de Control de Garantía de la Calidad', 'C', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.1.5. Estrategias y herramientas. Visita Domiciliaria y Ficha Familiar. Página 70, 77.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('67383187-9cfa-5074-ad1f-69956793e501', 'Caso clínico: Un distrito de salud busca fortalecer la organización territorial de sus establecimientos, estructurando redes zonales y distritales acorde a la nueva estructura desconcentrada, y fortaleciendo el sistema de referencia y contrarreferencia. Según el manual, ¿a qué objetivo estratégico del MAIS corresponde esta acción?', 'Objetivo estratégico 4.4.7, sobre la vigilancia epidemiológica', 'Objetivo estratégico 4.4.6, sobre la participación de la comunidad', 'Objetivo estratégico 4.4.1, sobre la reorientación del enfoque curativo', 'Objetivo estratégico 4.4.3, sobre el fortalecimiento de la organización territorial de los establecimientos de salud en la Red Pública Integral', 'D', 'Referencia: Capítulo 4. El Modelo de Atención Integral de Salud Familiar Comunitario e Intercultural. Sección 4.4.3. Objetivos estratégicos. Página 56.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('db80c502-b864-548e-918b-721879283cfe', 'Caso clínico: Un distrito rural con una población dispersa de 1.800 habitantes debe conformar su equipo de atención integral de salud correspondiente al primer nivel de atención. Según el manual, ¿qué conformación de equipo corresponde a esta población, considerando los estándares establecidos para el ámbito rural?', 'Un médico/a, una enfermera/o y un TAPS, dado que la población se encuentra dentro del rango de 1.500 a 2.500 habitantes establecido para el ámbito rural', 'Un equipo exclusivamente odontológico sin médico ni enfermera', 'Diez médicos especialistas de tercer nivel', 'Ningún equipo, ya que el estándar rural solo aplica a poblaciones mayores a 4.000 habitantes', 'A', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.2.2. Organización de los equipos de atención integral de salud. Página 89.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('24c5c176-4d97-5480-a5c8-c8fba0d6c792', 'Caso clínico: Un equipo de salud distrital debe realizar un diagnóstico de la situación de salud de su territorio para la planificación de sus actividades anuales, aplicando una herramienta metodológica de diagnóstico. Según el manual, ¿qué herramienta corresponde utilizar para este diagnóstico y a qué componente del MAIS-FCI pertenece?', 'La Ficha Familiar, dentro del componente de Financiamiento', 'El Análisis Situacional de Salud (ASIS), dentro del componente de Gestión del Sistema Nacional de Salud', 'El Sistema de Control de Garantía de la Calidad, dentro del componente de Provisión', 'El Tarjetero de citas, dentro del componente de Organización', 'B', 'Referencia: Capítulo 5. Componentes del MAIS-FCI. Sección 5.3.1. Herramientas de diagnóstico y monitoreo de las condiciones de salud. Página 98.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('5adf74cb-362a-5ec6-ae91-db892c76908e', 'Caso clínico: Un equipo de salud diseña una estrategia comunitaria que busca actuar sobre las condiciones de vivienda, ingresos y trabajo de las familias de su zona de cobertura, reconociendo que estas condiciones inciden directamente en su estado de salud. Según el manual, ¿sobre qué tipo de determinantes de la salud está actuando principalmente esta estrategia?', 'Determinantes exclusivamente genéticos', 'Determinantes biológicos exclusivamente', 'Los determinantes intermedios relacionados con las circunstancias materiales, como la vivienda, el nivel de ingresos y las condiciones de trabajo', 'El manual no reconoce estos factores como determinantes de la salud', 'C', 'Referencia: Capítulo 3. Marco conceptual del Modelo de Atención Integral de Salud. Sección 3.2. Determinantes de la Salud. Determinantes intermedios. Página 41.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018'),
  ('5068e61d-1662-518e-a502-eeb721a207f9', 'Caso clínico: Al finalizar una capacitación institucional, se solicita a los profesionales de enfermería resumir en una idea central la transformación que busca el MAIS-FCI respecto al modelo de atención anterior. Según el manual, ¿cuál es la transformación central que plantea el MAIS-FCI respecto al enfoque médico biologista predominante en el modelo anterior?', 'Mantener sin cambios el enfoque biologista centrado en la enfermedad y el individuo', 'Concentrar toda la atención exclusivamente en el nivel hospitalario', 'Eliminar por completo la atención curativa de los servicios de salud', 'Transformar el enfoque médico biologista hacia un enfoque integral en salud centrado en el cuidado y recuperación de la salud individual, familiar y comunitaria como un derecho humano', 'D', 'Referencia: Capítulo 4. El Modelo de Atención Integral de Salud Familiar Comunitario e Intercultural. Sección 4.2. Propósito del MAIS-FCI. Página 56.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'MAIS-FCI MSP 2018')
